public class Main {



    static Scanner sc;

    static PrintWriter out;



    public static void main(String[] args) {

        sc = new Scanner(System.in);

        out = new PrintWriter(System.out);

        new Main().solve();

        out.flush();

    }



    public void solve() {

        int n = sc.nextInt();

        int mg = sc.nextInt();

        boolean[][] g = new boolean[n][n];

        for (int i = 0; i < mg; i++) {

            int a = sc.nextInt() - 1;

            int b = sc.nextInt() - 1;

            g[a][b] = true;

            g[b][a] = true;

        }

        int mh = sc.nextInt();

        boolean[][]  h = new boolean[n][n];

        for (int i = 0; i < mh; i++) {

            int a = sc.nextInt() - 1;

            int b = sc.nextInt() - 1;

            h[a][b] = true;

            h[b][a] = true;

        }

        int[][] a = new int[n][n];

        for(int i=0; i<n; i++) {

            for(int j=i+1; j<n; j++) {

                a[i][j] = a[j][i] = sc.nextInt();

            }

        }

        int[] p = new int[n];

        for(int i=0; i<n; i++) {

            p[i] = i;

        }

        long res = Long.MAX_VALUE;

        do {

            long sum = 0;

            for(int i=0; i<n; i++) {

                for(int j=i+1; j<n; j++) {

                    if(g[p[i]][p[j]] ^ h[i][j]) {

                        sum += a[i][j];

                    }

                }

            }

            res = Math.min(res, sum);

        } while(nextPermutation(p));



        out.println(res);

    }



    private static boolean nextPermutation(int[] array) {

        for (int i = array.length - 1 ; i > 0 ; i --) {

            if (array[i - 1] < array[i]) {

                int j = find(array, array[i - 1], i, array.length - 1);

                int temp = array[j];

                array[j] = array[i - 1];

                array[i - 1] = temp;

                Arrays.sort(array, i, array.length);

                return true;

            }

        }

        return false;

    }

    private static int find(int[] array, int dest, int f, int l) {

        if (f == l) {

            return f;

        }

        int m = (f + l + 1) / 2;

        return (array[m] <= dest) ? find(array, dest, f, m - 1) : find(array, dest, m, l);

    }



}

