import java.util.*;



/*

 * B - Binary Alchemy

 */

class Main { // AtCoderはクラス名Mainのみ…

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);



        // 元素数

        final int N = sc.nextInt();



        // 配合表マップ

        Map<Integer, int[]> mapA = new HashMap<Integer, int[]>();



        // 配合表の取り込み

        for (int i = 1; i <= N; i++) {

            // 配合行

            int[] lineA = new int[N + 1];

            for (int j = 1; j <= i; j++) {

                lineA[j] = sc.nextInt();

            }

            // 配合行を配合表に設定

            mapA.put(i, lineA);

        }



        // System.out.print("------\n");

        // // 配合表のチェック

        // for (int i = 1; i <= N; i++) {

        //     System.out.print("key[" + i + "] - ");

        //     printIntArray(mapA.get(i));

        // }



        // 答え＝元素番号。初期値に１を設定

        int ans = 1;



        // 答えを計算。１から順に元素番号を取り出す

        for (int i = 1; i <= N; i++) {

            // 配合表の行番号・列番号

            int lineNo = 0, crumNo = 0;

            // 前回配合結果と比較してどの配合表の行番号列番号を対象とするか判定

            if(i >= ans) {

                lineNo = i;

                crumNo = ans;

            } else {

                lineNo = ans;

                crumNo = i;

            }

            // 判定された行列番号の元素番号を答え（次配合のインプット）に設定

            ans = mapA.get(lineNo)[crumNo];

            // System.out.println("ans  = " + ans);

        }

        // System.out.print("------\n");



        // 答えの出力

        System.out.println(ans);



        // スキャナーをクローズ

        sc.close();

        return;

    }



    private static void printAnswer(boolean answerFlag) {

        if (answerFlag) {

            System.out.println("Yes");

        } else {

            System.out.println("No");

        }

        return;

    }



    private static void printIntArray(int[] array) {

        for (int a : array) {

            System.out.print(a);

            System.out.print(" ");

        }

        System.out.print("\n");



        return;

    }



    private static void printStringArray(String[] array) {

        for (String a : array) {

            System.out.print(a);

            System.out.print(" ");

        }

        System.out.print("\n");



        return;

    }



    private static void printCharArray(char[] array) {

        for (char a : array) {

            System.out.print(a);

            System.out.print(" ");

        }

        System.out.print("\n");



        return;

    }

}

