import java.util.Arrays;

import java.util.HashMap;

import java.util.Map;

import java.util.Scanner;



public class Main {

    private static final long MOD = 998244353;



    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        int n;

        long k, prefixSum = 0L, totalAns = 1L, ans = 0L;

        n = sc.nextInt();

        k = sc.nextLong();

        long[] arr = new long[n];

        Arrays.setAll(arr, i -> sc.nextLong());

        Map<Long, Long> combinationsWithPrefixSum = new HashMap<>();

        combinationsWithPrefixSum.put(0L, 1L);

        for (int i = 0; i < n; i++) {

            prefixSum += arr[i];

            long totalSubsetsFromPrevPrefixes = combinationsWithPrefixSum.getOrDefault(prefixSum - k, 0L);

            ans = (totalAns - totalSubsetsFromPrevPrefixes + MOD) % MOD;

            totalAns = (totalAns + ans) % MOD;

            combinationsWithPrefixSum.put(prefixSum,

                    (combinationsWithPrefixSum.getOrDefault(prefixSum, 0L) + ans) % MOD);

        }

        System.out.println(ans);

    }

}

