		for (int i = 0; i < n; i++) {

			int p = scanner.nextInt();
			if (p == 0) {
				a[p]++;
				continue;
			}

			int result = 1;
			for (int j = 2; j <= Math.sqrt(p) + 1; j++) {
				int pow = 0;
				while (p % j == 0) {
					pow++;
					p /= j;
				}

				if (pow % 2 == 1) {
					result *= j;
				}
				if (p == 1) {
					break;
				}
			}

			if ( p != 1) {
				result *= p;
			}
			a[result]++;

		}


		long answer = 0;
		if (a[0] > 0) {
			answer = (n - a[0]) * a[0];
		}

		for (int i = 0; i <= 200000; i++) {
			if (a[i] > 1) {
				answer += ( a[i] * (a[i]-1) / 2 ) ;
			}
		}
		System.out.println(answer);
	}
}

