			for(int i = 0; i < n; i++) g.add(new ArrayList<Train>());

			for(int i = 0; i < m; i++) {
				long l = Long.parseLong(sc.next());
				long d = Long.parseLong(sc.next());
				long k = Long.parseLong(sc.next());
				long c = Long.parseLong(sc.next());
				int a = Integer.parseInt(sc.next());
				int b = Integer.parseInt(sc.next());
				a--;
				b--;
				g.get(b).add(new Train(a, l, d, k, c));
			}

			final long INF = 2L << 60;
			long[] a = new long[n];
			Arrays.fill(a, -INF);
			PriorityQueue<Pair> pq = new PriorityQueue<Pair>((p1, p2) -> {
				return Integer.compare(p1.u, p2.u);
			});

			a[n - 1] = INF;
			pq.add(new Pair(-INF, n - 1));

			while(!pq.isEmpty()) {
				long t = pq.peek().t;
				int u = pq.peek().u;
				pq.poll();
				t *= -1;
				if(t < a[u]) continue;

				for(Train tr : g.get(u)) {
					if(tr.l + tr.c <= t) {
						long x = t - (tr.l + tr.c);
						long nt = tr.l + Math.min(tr.k - 1, x / tr.d) * tr.d;
						if(a[tr.A] < nt) {
							a[tr.A] = nt;
							pq.add(new Pair(-nt, tr.A));
						}
					}
				}
			}

			StringBuilder sb = new StringBuilder();
			for(int i = 0; i < n - 1; i++) {
				if(a[i] > -INF) sb.append(a[i]);
				else sb.append("Unreachable");
				sb.append("\n");
			}

			System.out.print(sb.toString());
		}
	}
}

class Pair{
	long t;
	int u;

