from heapq import *

class HeapDict:
    def __init__(self, maxheap=False):
        self.q = []
        self.d = dict()
        self.c = 0
        self.sign = 1
        if maxheap:
            self.sign = -1

    def add(self, val):
        self.c += 1
        val *= self.sign
        if val not in self.d:
            heappush(self.q, val)
            self.d[val] = 1
        else:
            self.d[val] += 1

    def remove(self, val):
        val *= self.sign
        if val not in self.d:
            return
        self.c -= 1
        self.d[val] -= 1
        if self.d[val] == 0:
            del self.d[val]
        while self.q and self.q[0] not in self.d:
            heappop(self.q)

    def count(self, val):
        val *= self.sign
        if val in self.d:
            return self.d[val]
        return 0

    def top(self):
        return self.q[0] * self.sign

    def pop(self):
        ret = self.top()
        self.remove(ret)
        return ret

    def count_keys(self):
        return len(self.d)

    def keys(self):
        return [i * self.sign for i in self.q if i in self.d]

    def __len__(self):
        return self.c

