    for(int q = 0; q < Q; q++) {
      int type = sc.nextInt();
      int L = sc.nextInt();
      int R = sc.nextInt();
      if ( type == 1 ) {
        d.inverse(L, R);
      }
      else if ( type == 2 ) {
        d.output(L, R);
      }
    }
  }

  private static class Data {
    private final int N;

    private final long[] data;
    private final Segtree seg;

    public Data(String S) {
      N = S.length();
      data = new long[N-1];
      for(int i = 0; i < N-1; i++) {
        char c = S.charAt(i);
        char nx = S.charAt(i+1);
        data[i] = c != nx ? 0 : 1;
      }
      seg = new Segtree(N-1, data, 0);
      dump();
    }

    public void inverse(int L, int R) {
      if ( L > 1 ) {
        data[L-2] = 1L - data[L-2];
        seg.update(L-2, data[L-2]);
      }
      if ( R < N ) {
        data[R-1] = 1L - data[R-1];
        seg.update(R-1, data[R-1]);
      }
      dump();
    }

    private void dump() {
      if(!DEBUG) return;
      System.out.print("DEBUG:");
      for(int i = 0; i < N-1; i++) {
        System.out.print(data[i] == 0 ? "T" : "F");
      }
      System.out.println();
    }

    public void output(int L, int R) {
      System.out.println(isGood(L, R) ? "Yes" : "No");
    }

    private boolean isGood(int L, int R) {
      return seg.query(L-1, R-1) == 0;
    }
  }

  private static class Segtree{
		int N;
		long dat[];
		long identity;
		public Segtree(int N,long identity) {
			init(N, identity);
		}
		public Segtree(int N,long A[],long identity) {
			init(N, identity);
			init2(N,A, identity);
		}
		private void init(int N,long identity) {
			int a=1;
			while(a<=N)a*=2;
			dat=new long[a*2-1];
			this.identity=identity;
			this.N=a;
			Arrays.fill(dat, identity);
		}
		private void init2(int N,long A[],long identity) {

			for(int i=this.N-1;i<this.N-1+N;i++) {
				dat[i]=A[i-this.N+1];
			}
			for(int i=dat.length-1;i>0;i-=2) {
				dat[(i-1)/2]=cal(dat[i], dat[i-1]);
			}

		}
		private long get(int K) {
			return dat[N-1+K];
		}
		private void update(int K,long X) {
			K+=(N-1);
			dat[K]=X;
			while(K>0) {
				K--;
				K/=2;
				dat[K]=cal(dat[K*2+1], dat[K*2+2]);
			}
		}

		public long query(int a, int b) {
		  return query1(a, b, 0, N, 0);
		}

		//[a,b)について求める。外からの呼び出しquery1(a,b,0,N,0)
		private long query1(int a,int b,int x,int y,int k) {
			//kは[x,y)を表すノードのインデックス
			//求めたいのは[a,b)
			//区間に完全に含まれていれば値を返す
			//一部含まれていれば子供にに、
			//全く含まれてなければidentityを返す。

			//[x,y)が[a,b)に含まれているか
			if(a<=x&&y<=b) {
				//完全に含まれる
				return dat[k];
			}
			if(y<=a||b<=x) {
				//完全に含まれない
				return identity;
			}
			//一部含まれる
			return cal(query1(a, b, x, (x+y)/2, k*2+1), query1(a, b, (x+y)/2, y, k*2+2));
		}
		private long cal(long a,long b) {
			return a + b;
		}
	}

