import java.io.*;
import java.util.*;

class Main {
    public static void main(String[] args) {
	new Main().solve();
    }

    void solve() {
	Reader in = new Reader(System.in);
	PrintWriter out = new PrintWriter(System.out);

	long x = in.nextLong();
	long y = in.nextLong();
	Math.ExtGcdResult res = Math.extGcd(x, -y);
	if (res.g == 1) {
	    out.printf("%d %d\n", res.b * 2, res.a * 2);
	} else if (res.g == 2) {
	    out.printf("%d %d\n", res.b, res.a);
	} else {
	    out.println("-1");
	}
	out.flush();
    }
}

class Math {
    static class ExtGcdResult {
	// ax + by == g;
	long g;
	long a;
	long b;
	ExtGcdResult(long g, long a, long b) {
	    this.g = g;
	    this.a = a;
	    this.b = b;
	}
    }

    static ExtGcdResult extGcd(long x, long y) {
	// Find a, b: (x, 1, 0)*a + (y, 0, 1)*b == (g, a, b);
	boolean xNeg = (x < 0);
	boolean yNeg = (y < 0);
	if (x < 0) { x = -x; }
	if (y < 0) { y = -y; }
	long c = 1;
	long d = 0;
	long e = 0;
	long f = 1;

	while (true) {
	    if (x == 0) { return new ExtGcdResult(y, xNeg? -e: e, yNeg? -f: f); }
	    long q = y / x;
	    y -= q * x;
	    e -= q * c;
	    f -= q * d;
	    if (y == 0) { return new ExtGcdResult(x, xNeg? -c: c, yNeg? -d: d); }
	    q = x / y;
	    x -= q * y;
	    c -= q * e;
	    d -= q * f;
	}
    }
}

class Reader {
    BufferedReader br;
    StringTokenizer st;
    Reader(InputStream is) {
	br = new BufferedReader(new InputStreamReader(is));
	st = null;
    }
    String next() {
	while (st == null || !st.hasMoreTokens()) {
	    try {
		st = new StringTokenizer(br.readLine());
	    } catch (Exception e) {
		e.printStackTrace();
	    }
	}
	return st.nextToken();
    }
    int nextInt() {
	return Integer.parseInt(next());
    }
    long nextLong() {
	return Long.parseLong(next());
    }
}

