        Scanner scanner = new Scanner(System.in);



        int p, b, n, m;

        p = scanner.nextInt();

        b = scanner.nextInt();

        n = scanner.nextInt();

        m = scanner.nextInt();



        n += 1;

        int n2 = 1 << n;



        int[] links = new int[n];

        for (int i = 0; i < m; i++) {

            int l = scanner.nextInt();

            int r = scanner.nextInt();

            l -= 1;

            links[l] |= 1 << r;

            links[r] |= 1 << l;

        }



        if (n <= p) {

            System.out.println("Yes");

            System.exit(0);

        }



