        int[] pm = new int[n2];

        pm[0] = 1;

        for (int i = 1; i < n2; i++) {

            int lsb = i & -i;

            pm[i] = pm[i ^ lsb] * -1;

        }



        // Reverse the pm array

        for (int i = 0, j = n2 - 1; i < j; i++, j--) {

