import java.util.Scanner;



public class Main {



	static final int MSTSZ = 262144;

	static long soll, solr;

	static long solx;



	public static void main(String[] args) {

		try(Scanner sc = new Scanner(System.in);) {

			int n = Integer.parseInt(sc.next());

			List<Long> a = new ArrayList<Long>();

			for(int i = 0; i < n; i++) a.add(Long.parseLong(sc.next()));

			final long big = 2000000000;

			while(a.size() < MSTSZ) {a.add(big);}



			List<List<Long>> mst = new ArrayList<List<Long>>();

			for(int i = 0; i < 2 * MSTSZ; i++) mst.add(new ArrayList<Long>());



			for(int i = 0; i < MSTSZ; i++){

				mst.get(MSTSZ - 1 + i).add(a.get(i));

			}



			for(int i = MSTSZ - 2; i >= 0; i--) {

				mst.set(i, merge(mst.get(2 * i + 1), mst.get(2 * i + 2)));

			}



			List<List<Long>> sum = new ArrayList<List<Long>>();

			for(int i = 0; i < mst.size(); i++) sum.add(new ArrayList<Long>(mst.get(i)));

			for(List<Long> nx : sum) {

				int l = nx.size();

				for(int i = 1; i < l; i++) {

					long v = nx.get(i - 1);

					nx.set(i, nx.get(i) + v);

				}

			}



			int q = Integer.parseInt(sc.next());

			long b = 0;

			StringBuilder sb = new StringBuilder();

			while(q > 0) {

				q--;

