import java.util.Scanner;

public class Main {
    static int H, W, K, result = 0;
    static char[][] grid;
    static boolean[][] visited;
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        H = scanner.nextInt();
        W = scanner.nextInt();
        K = scanner.nextInt();
        grid = new char[H][W];
        visited = new boolean[H][W];
        for (int i = 0; i < H; i++) grid[i] = scanner.next().toCharArray();
        for (int i = 0; i < H; i++) 
        {
            for (int j = 0; j < W; j++) 
            {
                if (grid[i][j] == '.') 
                {
                    dfs(i, j, 0);
                }
            }
        }

        System.out.println(result);
    }
    static int[] dx = {-1, 1, 0, 0};
    static int[] dy = {0, 0, -1, 1};
    static void dfs(int x, int y, int steps) 
    {
        if (steps == K) 
        {
            result++;
            return;
        }
        visited[x][y] = true;
        for (int d = 0; d < 4; d++) 
        {
            int nx = x + dx[d], ny = y + dy[d];
            if (nx >= 0 && nx < H && ny >= 0 && ny < W && grid[nx][ny] == '.' && !visited[nx][ny]) 
            {
                dfs(nx, ny, steps + 1);
            }
        }
        visited[x][y] = false;
    }
}

