import java.io.*;
import java.util.StringTokenizer;

public class Main {
    private static BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
    private static BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(System.out));
    private static StringTokenizer st;

    public static void main(String[] args) throws IOException {
        st = new StringTokenizer(reader.readLine());
        int N = Integer.parseInt(st.nextToken());
        long M = Integer.parseInt(st.nextToken());
        st = new StringTokenizer(reader.readLine());
        long[] A = new long[N];
        for (int i = 0; i < N; i++) {
            A[i] = Integer.parseInt(st.nextToken());
        }
        long modSum = 0;
        for (int i = 0; i < N; i++) {
            modSum = (modSum + (long)(i + 1) * (N - i) % M * A[i] % M) % M;
        }
        SumSegmentTree mults = new SumSegmentTree(new long[(int)M]);
        SumSegmentTree sums = new SumSegmentTree(new long[(int)M]);
        long result = 0;
        long sum = 0;
        for (int i = 0; i < N; i++) {
//            System.out.println(i);
//            System.out.println(mults);
//            System.out.println(sums);
//            System.out.println(result);
            sum = (sum + A[i]) % M;
            result += (i + 1) * sum - sums.query(0, (int)sum) - mults.query((int)sum, (int)sum + 1) * sum + mults.query((int)sum + 1, (int)M) * M - sums.query((int)sum + 1, (int)M);
//            System.out.println(result);
//            System.out.println("----");
            mults.modify((int)sum, mults.query((int)sum, (int)sum + 1) + 1);
            sums.modify((int)sum, sums.query((int)sum, (int)sum + 1) + sum);
        }
        writer.write(Long.toString(result));
        writer.newLine();
        writer.flush();
    }

    static class SumSegmentTree {
        int n;
        long[] t;

        public SumSegmentTree(long[] arr) {
            n = arr.length;
            t = new long[2 * n];
            System.arraycopy(arr, 0, t, n, n);
            for (int i = n - 1; i > 0; --i) {
                t[i] = t[i<<1] + t[i<<1|1];
            }
        }

        public void modify(int p, long value) {  // set value at position p
            for (t[p += n] = value; p > 1; p >>= 1) t[p>>1] = t[p] + t[p^1];
        }

        public long query(int l, int r) {  // sum on interval [l, r)
            long res = 0;
            for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
                if ((l&1) != 0) res = res + t[l++];
                if ((r&1) != 0) res = t[--r] + res;
            }
            return res;
        }

        @Override
        public String toString() {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++) {
                sb.append(query(i, i + 1));
                sb.append(" ");
            }
            return sb.toString();
        }
    }
}

