import java.util.*;
public class Main{
    public static void main(String args[]){
        Scanner sc=new Scanner(System.in);
        int a=sc.nextInt(),b=sc.nextInt(),m=sc.nextInt();
        Map<Count,Integer> map[]=new Map[a*b+5];
        map[1]=new HashMap<>();
        Count count=new Count(b);
        count.count[0]=1;
        map[1].put(count,1);
        long ans=fac(a*b-1,m);
        for(int i=2;i<a*b;i++){
            map[i]=new HashMap<>();
            for(Map.Entry<Count,Integer> entry:map[i-1].entrySet()){
                Count cur=entry.getKey();
                int num=entry.getValue();
                for(int j=0;j<b;j++){
                    if(j<b-1&&cur.count[j]==a||j==b-1&&cur.count[j]==a-1){
                        //每一行的数字数量不能超限
                        continue;
                    }
                    if(j>0&&cur.count[j]==cur.count[j-1]){
                        //上一行长度必须不小于下一行
                        continue;
                    }
                    if(j+1<b&&cur.count[j]+1==a&&cur.count[j+1]<a-1){
                        //最右边一列的数字要大于左下角的数字
                        continue;
                    }
                    Count temp=new Count(b);
                    temp.count=cur.count.clone();
                    temp.count[j]++;
                    map[i].put(temp,(map[i].getOrDefault(temp,0)+num)%m);
                }
            }
        }
        for(int i=0;i<a;i++){
            for(int j=0;j<b;j++){
                if(i==a-1&&j==b-1){
                    break;
                }
                ans=ans*pow(a+b-i-j-(i==a-1||j==b-1?2:1),m-2,m)%m;
            }
        }
        for(int p:map[a*b-1].values()){
            ans=ans*p%m;
        }
        System.out.println(ans);
    }
    static long pow(long a,long b,int m){
        long ans=1;
        for(;b!=0;b>>=1,a=a*a%m){
            if(b%2==1){
                ans=ans*a%m;
            }
        }
        return ans;
    }
    static long fac(int a,int m){
        return a==0?1:fac(a-1,m)*a%m;
    }
}
class Count{
    int count[],base=157,mod=(int)1e9+9;
    public Count(int n){
        count=new int[n];
    }
    public int hashCode(){
        long hash=0;
        for(int i=0;i<count.length;i++){
            hash=((hash+i+1)*base+count[i])%mod;
        }
        return (int)hash;
    }
    public boolean equals(Object obj){
        return this==obj||this.hashCode()==obj.hashCode();
    }
}

