    public static void main(String[] args) {

        FastScanner sc = new FastScanner();

        PrintWriter out = new PrintWriter(System.out);



        int N = sc.nextInt();

        int[] Q = new int[N];

        int[] A = new int[N];

        int[] B = new int[N];

        for (int i = 0; i < N; i++) Q[i] = sc.nextInt();

        for (int i = 0; i < N; i++) A[i] = sc.nextInt();

        for (int i = 0; i < N; i++) B[i] = sc.nextInt();



        int ans = 0;

        for (int a = 0; a < (int)(Math.pow(10, 6) + 1); a++) {

            int[] _Q = Q.clone();

            boolean flag = true;



            //Aをa人分作る

            for (int i = 0; i < N; i++) {

                if (A[i] == 0) continue;



                if (_Q[i] / A[i] < a) {

                    flag = false;

                    break;

                }

                else {

                    _Q[i] -= A[i] * a;

                }

            }

            //作れないならループ終了

            if (!flag) break;



            //残りでBを作る

            Integer b = Integer.MAX_VALUE;

            for (int i = 0; i < N; i++) {

                if (B[i] == 0) continue;

                b = Math.min(b, _Q[i] / B[i]);

            }



            ans = Math.max(ans, a+b);

        }



        out.println(ans);

        out.flush();

    }

    //-----------------------------------------------------------------------------------------------------------------------------------



