import java.util.Scanner;

public class Main {

    public static void main(String[] args) {

        Scanner input = new Scanner(System.in);

        String S = input.nextLine();

        //array to store the count of the alphabet in the string

        int[] frequencies = new int[26];

        //array to store entire alphabet

        char[] alphabet = {'a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 

                          'j', 'k', 'l', 'm', 'n', 'o', 'p', 'q', 'r', 's',

                          't', 'u', 'v', 'w', 'x', 'y', 'z'};



        for(int i = 0; i < S.length(); i++) {

          //match alphabet to current letter

          for(int j = 0; j < alphabet.length; j++) {

            if(alphabet[j] == S.charAt(i)) {

              frequencies[j]++;

            }

          }

        }



        int maxFrequency = 0;

        //set current answer to z's index

        int currentAnswer = alphabet.length-1;

        for(int i = 0; i < frequencies.length; i++) {

          if(frequencies[i] > maxFrequency) {

            currentAnswer = i;

            maxFrequency = frequencies[i];

          }

        }



        char answer = alphabet[currentAnswer];

        System.out.print(answer);

    }

}

