import sys

from collections import Counter

# sys.setrecursionlimit(10000)





def input_general():

    return sys.stdin.readline().rstrip('\r\n')





def input_num():

    return int(sys.stdin.readline().rstrip("\r\n"))





def input_multi(x=int):

    return map(x, sys.stdin.readline().rstrip("\r\n").split())





def input_list(x=int):

    return list(input_multi(x))





def power(p, x, e):

    base = x

    answer = 1

    while e:

        if e & 1:

            answer = (answer * base) % p



        base = (base * base) % p

        e >>= 1



    return answer





def main():

    n, m = input_multi()

    arr = input_list()

    ctr = Counter(arr)

    mod = 998244353



    if ctr[1] == 0:

        print(power(mod, m, n))

        return

    if m + 1 >= n:

        print(power(mod, m, ctr[0]))

        return



    dp = [1] + [0] * (m + 1)

    for x in arr:

        temp = [0] * (m + 2)



        if x == 0:

            for i in range(m + 2):

                temp[i] += dp[i] * i



            for i in range(m + 1):

                temp[i + 1] += dp[i] * (m - i)



        else:  # x == 1

            for i in range(1, m + 2):

                temp[i] += dp[i - 1]



        dp = [x % mod for x in temp]



    answer = sum(dp) % mod

    print(answer)





