      int[] array = new int[n+1];
      for(int k = 1; k <= n; k++){
         array[k] = Integer.parseInt(st.nextToken());
      }

      Stack<Range> stack = new Stack<Range>();
      for(int k = n; k >= 1; k--){
         if(array[k] == k-1){
            stack.push(new Range(array[k],k,1L));
         } else {
            stack.push(new Range(array[k],k,-1L));
         }

         //compress stack
         while(stack.size() >= 2){
            Range top = stack.pop();
            if(top.computed != -1 && stack.peek().l == top.l){
               stack.peek().computed = top.computed;
            } else if(top.computed != -1 && stack.peek().computed != -1){
               //combine
               Range top2 = stack.pop();
               long prod = (top.computed * top2.computed + MOD)%MOD;
               prod = (prod * choose(top2.r-top.l-1,top2.r-top2.l) + MOD)%MOD;
               stack.push(new Range(top.l,top2.r,prod));
            } else {
               stack.push(top);
               break;
            }
         }
      }

      //should only have 1 element left
      long answer = stack.peek().computed;
      out.println(answer);






      out.close();
   }

   public static long choose(int n, int r){
      long prod = (fac[n] * ifac[r] + MOD)%MOD;
      return (prod * ifac[n-r] + MOD)%MOD;
   }

   public static class Range{
      int l;
      int r;
      //-1 means uncomputed
      long computed;
      public Range(int a, int b, long c){
         l = a;
         r = b;
         computed = c;
      }
   }

