import java.util.*;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int M = sc.nextInt();
		int[] L = new int[N+1];
		int[] R = new int[N+1];
		Map<Integer, List<Integer>> m = new HashMap<>();
		for(int i=1;i<=N;i++) {
			int l=sc.nextInt();
			int r=sc.nextInt();
			L[i]=l;
			R[i]=r;
			if(m.containsKey(r)) {
				m.get(r).add(l);
			}else {
				List<Integer> list = new ArrayList<>();
				list.add(l);
				m.put(r, list);
			}
		}

		int r=1;
		long ans = 0;

		for(int l=1;l<=M;l++) {
			while(r<=M && ok(l,r, m) ) {
				r++;
			}
			int n = r-l;
			ans+=n;
		}


		System.out.println(ans);
	}


	static boolean ok(int l, int r, Map<Integer, List<Integer>> m) {
		if(!m.containsKey(r)) {
			return true;
		}

		for(int L : m.get(r)) {
			if(l<=L) {
				return false;
			}
		}

		return true;
	}
}

