      int[] a = new int[n];

      int[] b = new int[n];

      int bsum = 0;

      int bmax = 0;



      for(int k = 0; k < n; k++){

         StringTokenizer st = new StringTokenizer(f.readLine());



         a[k] = Integer.parseInt(st.nextToken());

         b[k] = Integer.parseInt(st.nextToken());

         bsum += b[k];

         bmax = Math.max(b[k],bmax);

      }



