         out.println("-1");

         out.close();

         return;

      }



      int B = bsum/3;

      int[][][] dp = new int[2][B+1][B+1];

      for(int k = 0; k <= B; k++){

         for(int j = 0; j <= B; j++){

            dp[0][k][j] = Integer.MAX_VALUE;

            dp[1][k][j] = Integer.MAX_VALUE;  

         }

      }



      //place first person

      if(a[0] == 1) dp[0][b[0]][0] = 0;

      else dp[0][b[0]][0] = 1;

      if(a[0] == 2) dp[0][0][b[0]] = 0;

      else dp[0][0][b[0]] = 1;

      if(a[0] == 3) dp[0][0][0] = 0;

      else dp[0][0][0] = 1;



      for(int k = 1; k < n; k++){

         int to = (k&1);

         int from = 1-to;



         for(int x = 0; x <= B; x++){

            for(int y = 0; y <= B; y++){

               if(dp[from][x][y] == Integer.MAX_VALUE) continue;

               if(x+b[k] <= B){

                  if(a[k] == 1) dp[to][x+b[k]][y] = Math.min(dp[to][x+b[k]][y], dp[from][x][y]);

                  else dp[to][x+b[k]][y] = Math.min(dp[to][x+b[k]][y], dp[from][x][y] + 1);

               }

               if(y+b[k] <= B){

                  if(a[k] == 2) dp[to][x][y+b[k]] = Math.min(dp[to][x][y+b[k]], dp[from][x][y]);

                  else dp[to][x][y+b[k]] = Math.min(dp[to][x][y+b[k]], dp[from][x][y] + 1);

               }

               if(a[k] == 3) dp[to][x][y] = Math.min(dp[to][x][y],dp[from][x][y]);

               else dp[to][x][y] = Math.min(dp[to][x][y],dp[from][x][y] + 1);

            }

         }



         for(int x = 0; x <= B; x++){

            for(int y = 0; y <= B; y++){

               dp[from][x][y] = Integer.MAX_VALUE;

            }

         }

      }





      int answer = dp[(n-1)&1][B][B];

      if(answer == Integer.MAX_VALUE) answer = -1;



      out.println(answer);







      out.close();

   }





}

