import java.io.*;

import java.util.*;



public class Main {



    public static List<int[]>[] edges;

    public static int n, mod = (int) (1e9 + 7);



    public static void bfs(long[] dis, long[] f, int s) {

        Arrays.fill(dis, (long) 1e18);

        dis[s] = 0;

        PriorityQueue<long[]> que = new PriorityQueue<>(new Comparator<long[]>() {

            @Override

            public int compare(long[] o1, long[] o2) {

                return Long.compare(o1[1], o2[1]);

            }

        });

        que.add(new long[]{s, 0});

        f[s] = 1;

        while (!que.isEmpty()) {

            long[] arr = que.poll();

            int u = (int) arr[0];

            long w = arr[1];

            if (dis[u] < w) continue;

            for (int[] edge : edges[u]) {

                int v = edge[0], val = edge[1];

                if (w + val < dis[v]) {

                    dis[v] = w + val;

                    f[v] = f[u];

                    que.add(new long[]{v, dis[v]});

                }else if (w + val == dis[v]) f[v] = (f[u] + f[v]) % mod;

            }

        }

    }



    public static void solve() throws IOException{

        int n = in.nextInt();

        int m = in.nextInt();

        int[][] a = new int[m][3];

        edges = new ArrayList[n+1];

        Arrays.setAll(edges, e -> new ArrayList<>());

        for (int i = 0; i < m; i++) {

            a[i][0] = in.nextInt();

            a[i][1] = in.nextInt();

            a[i][2] = in.nextInt();

            edges[a[i][0]].add(new int[]{a[i][1], a[i][2]});

            edges[a[i][1]].add(new int[]{a[i][0], a[i][2]});

        }

        long[] dis1 = new long[n+1];

        long[] f1 = new long[n+1];

        bfs(dis1, f1, 1);

        long[] disN = new long[n+1];

        long[] fN = new long[n+1];

        bfs(disN, fN, n);

        for (int i = 0; i < m; i++) {

            int u = a[i][0], v = a[i][1], w = a[i][2];

            if (dis1[u] > dis1[v]) {

                int t = u;

                u = v;

                v = t;

            }

            if (dis1[u] + disN[v] + w == dis1[n] && f1[u] * fN[v] % mod == f1[n]) out.println("Yes");

            else out.println("No");

        }

    }



    static boolean MULTI_CASE = false;



    public static void main(String[] args) throws IOException {

        if (MULTI_CASE) {

            int T = in.nextInt();

            for (int i = 0; i < T; ++i) {

                solve();

            }

        } else {

            solve();

        }

        out.close();

    }



    static InputReader in = new InputReader();

    static PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));



    static class InputReader {

        private StringTokenizer st;

        private BufferedReader bf;



        public InputReader() {

