public class Main

{

	public static void main (String[] args) throws java.lang.Exception

	{

		// your code goes here

		Scanner sc=new Scanner(System.in);

		int t=1;

		while(t-->0)

		{

		    int h=sc.nextInt();

		    int w=sc.nextInt();

		    int n=sc.nextInt();

		    ArrayList<Pair> al=new ArrayList<>();



		    for(int i=0;i<n;i++)

		    {

		        al.add(new Pair(sc.nextInt(),sc.nextInt()));

		    }

		    Collections.sort(al,(a,b)->{

		        if(a.x==b.x)

		        return a.y-b.y;

		        else return a.x-b.x;

		    });

		    Node tree[]=new Node[4*w+1];

		    for(int i=0;i<=4*w;i++)

		    tree[i]=new Node(0,-1);

		    int par[]=new int[n];

		    for(int i=0;i<n;i++)

		    {

		        Node q=Seg.query(tree,1,w,1,al.get(i).y,1);

		        par[i]=q.ind;

		        Seg.pointupdate(tree,1,w,al.get(i).y,q.score+1,i,1);

		    }

		    Node anss=Seg.query(tree,1,w,1,w,1);

		    int currx=h,curry=w;

		    int index=anss.ind;

		    StringBuilder sb=new StringBuilder();

		    while(index!=-1)

		    {

		       // System.out.println(al.get(index).x+" "+al.get(index).y);

		        while(currx>al.get(index).x){

		        sb.append("D");currx--;}

		        while(curry>al.get(index).y){

		        sb.append("R");curry--;}

		        index=par[index];



		    }

		    while(currx-->1)

		    sb.append("D");

		    while(curry-->1)

		    sb.append("R");

		    System.out.println(anss.score);

		    System.out.println(sb.reverse());



		}



	}

}

class Seg

{

    static Node identity=new Node(0,-1);

    public static Node merge(Node a,Node b)

    {

        if(a.score>b.score)

        return a;

        else return b;

    }

    static Node query(Node tree[],int ss,int se,int qs,int qe,int index)

    {

        if(ss>=qs && se<=qe)

        return tree[index];

        else if(qe<ss || qs>se)

        return identity;

        int mid=(ss+se)/2;

        Node low1=query(tree,ss,mid,qs,qe,2*index);

        Node low2=query(tree,mid+1,se,qs,qe,2*index+1);

        return merge(low1,low2);

    }

     public static void pointupdate(Node tree[],int ss,int se,int l,int inc,int ind,int index)

    {

        if(l<ss || l>se)

        return;

        if(ss==se){

        tree[index].score=inc; tree[index].ind=ind;return;}

        int mid=(ss+se)/2;

        pointupdate(tree,ss,mid,l,inc,ind,2*index);

        pointupdate(tree,mid+1,se,l,inc,ind,2*index+1);

        tree[index]=merge(tree[2*index],tree[2*index+1]);



    }

}

class Node

{

    int score,ind;

    Node(int score,int ind)

    {

        this.score=score;

        this.ind=ind;

    }

}

class Pair

{

    int x,y;

    Pair(int x,int y)

    {

        this.x=x;

        this.y=y;

    }

}

