import java.io.*;

import java.util.*;



public class Main{



   public static long MOD = 998244353L;



   public static long[] fac;

   public static long[] ifac;



   public static int[][] res;



   public static long[][] dp;



   public static void main(String[] args)throws IOException{

      BufferedReader f = new BufferedReader(new InputStreamReader(System.in));

      PrintWriter out = new PrintWriter(System.out);



      int N = 505;

      fac = new long[N];

      fac[0] = 1L;

      for(int k = 1; k < N; k++){

         fac[k] = (fac[k-1] * (long)k + MOD)%MOD;

      }

      ifac = new long[N];

      ifac[N-1] = modInverse(fac[N-1],MOD);

      for(int k = N-2; k >= 0; k--){

         ifac[k] = (ifac[k+1] * (long)(k+1) + MOD)%MOD;

      }



      StringTokenizer st = new StringTokenizer(f.readLine());



      int n = Integer.parseInt(st.nextToken());

      int m = Integer.parseInt(st.nextToken());



      //restrictions res[x][y] -> where the bigger element needs to be if center is x and closest greater element to the left of x is at y

      //y = 0 means no closest element to the left

      res = new int[n+1][n+1];

      for(int k = 0; k <= n; k++) Arrays.fill(res[k],n+1);



      for(int k = 0; k < m; k++){

         st = new StringTokenizer(f.readLine());



         int l = Integer.parseInt(st.nextToken());

         int r = Integer.parseInt(st.nextToken());

         int x = Integer.parseInt(st.nextToken());



         res[x][l-1] = Math.min(res[x][l-1],r);

      }



      for(int x = 1; x <= n; x++){

         //suffix min

         for(int y = n-1; y >= 0; y--){

            res[x][y] = Math.min(res[x][y],res[x][y+1]);

         }

      }



      dp = new long[n+1][n+1];

      for(int k = 0; k <= n; k++) Arrays.fill(dp[k],-1);

      long answer = dothing(1,n);



      out.println(answer);





      out.close();

   }





   public static long dothing(int l, int r){

      if(l > r) return 1L;

      if(dp[l][r] != -1) return dp[l][r];



      //pick max in the range (if possible)

      dp[l][r] = 0L;

      for(int c = l; c <= r; c++){

         if(res[c][l-1] > r){

            //possible to pick c

            long left = dothing(l,c-1);

            long right = dothing(c+1,r);

            long mul = choose(r-l+1 - 1, c-1 -l + 1);



            long prod = (left * right + MOD)%MOD;

            prod = (prod * mul + MOD)%MOD;

            dp[l][r] += prod;

            if(dp[l][r] >= MOD) dp[l][r] -= MOD;

         }

      }





      return dp[l][r];

   }







   public static long choose(int n, int r){

      long prod = (fac[n] * ifac[r] + MOD)%MOD;

      return (prod * ifac[n-r] + MOD)%MOD;

   }



