import java.io.BufferedReader;

import java.io.InputStreamReader;

import java.io.PrintWriter;

import java.util.ArrayDeque;

import java.util.ArrayList;

import java.util.List;

import java.util.PriorityQueue;

import java.util.Queue;



public class Main {

	static int n;

	static List<List<Integer>> list;

	static int[] dp;

	static int g;



	public static void main(String[] args) throws Exception {

		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

		String[] sa = br.readLine().split(" ");

		n = Integer.parseInt(sa[0]);

		list = new ArrayList<>(n);

		for (int i = 0; i < n; i++) {

			list.add(new ArrayList<>());

		}

		for (int i = 0; i < n - 1; i++) {

			sa = br.readLine().split(" ");

			int a = Integer.parseInt(sa[0]) - 1;

			int b = Integer.parseInt(sa[1]) - 1;

			list.get(a).add(b);

			list.get(b).add(a);

		}

		br.close();



		dp = new int[n];

		g = -1;

		dfs(0, -1);

		dfs2(g, -1);



		PriorityQueue<Obj> que = new PriorityQueue<>();

		for (int i : list.get(g)) {

			Obj o = new Obj();

			o.num = dp[i];

			dfs3(i, g, o.que);

			que.add(o);

		}



		int n2 = n / 2;

		PrintWriter pw = new PrintWriter(System.out);

		for (int i = 0; i < n2; i++) {

			Obj o1 = que.poll();

			Obj o2 = que.poll();

			int i1 = o1.que.poll() + 1;

			if (o2 == null) {

				int i2 = g + 1;

				pw.println(i1 + " " + i2);

				break;

			}

			int i2 = o2.que.poll() + 1;

			pw.println(i1 + " " + i2);

			o1.num--;

			o2.num--;

			if (o1.num > 0) {

				que.add(o1);

			}

			if (o2.num > 0) {

				que.add(o2);

			}

		}

		pw.flush();

	}



	static class Obj implements Comparable<Obj> {

		int num;

		Queue<Integer> que = new ArrayDeque<>();



		@Override

		public int compareTo(Obj o) {

			if (num % 2 == 1) {

				return -1;

			}

			if (o.num % 2 == 1) {

				return 1;

			}

			return o.num - num;

		}

	}



	static int dfs(int x, int p) {

		int ret = 1;

		for (int c : list.get(x)) {

			if (c != p) {

				int res = dfs(c, x);

				ret += res;

			}

		}

		if (g == -1 && ret * 2 >= n) {

			g = x;

		}

		return dp[x] = ret;

	}



	static int dfs2(int x, int p) {

		int ret = 1;

		for (int c : list.get(x)) {

			if (c != p) {

				int res = dfs2(c, x);

				ret += res;

			}

		}

		return dp[x] = ret;

	}



	static void dfs3(int x, int p, Queue<Integer> que) {

		for (int c : list.get(x)) {

			if (c != p && dp[c] % 2 == 1) {

				dfs3(c, x, que);

			}

		}

		for (int c : list.get(x)) {

			if (c != p && dp[c] % 2 == 0) {

				dfs3(c, x, que);

			}

		}

		que.add(x);

	}

}

