import java.util.Scanner;



public class Main {

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);



        // 入力の取得

        int deckSize = sc.nextInt(); // カードの枚数

        int cardsToMove = sc.nextInt(); // 移動するカードの枚数

        int[] deck = new int[deckSize]; // カードの山



        // カードの読み込み

        for (int i = 0; i < deckSize; i++) {

            deck[i] = sc.nextInt();

        }



        // 新しいカードの山を作成するための配列

        int[] newDeck = new int[deckSize];



        // 移動するカードを新しい山の先頭に配置

        for (int i = 0; i < cardsToMove; i++) {

            newDeck[i] = deck[deckSize - cardsToMove + i];

        }



        // 残りのカードを新しい山の後ろに配置

        for (int i = 0; i < deckSize - cardsToMove; i++) {

            newDeck[cardsToMove + i] = deck[i];

        }



        // 結果の出力

        for (int i = 0; i < deckSize; i++) {

            System.out.print(newDeck[i] + " ");

        }

    }

}

