import sys

sys.setrecursionlimit(10**6)



grundy_memo = {}



def calculate_grundy(n):

    if n in grundy_memo:

        return grundy_memo[n]



    divisors = set()

    for i in range(1, int(n ** 0.5) + 1):

        if n % i == 0:

            if i != n:

                divisors.add(i)

            if n // i != n:

                divisors.add(n // i)



    grundy_values = {calculate_grundy(d) for d in divisors}



    mex = 0

    while mex in grundy_values:

        mex += 1



    grundy_memo[n] = mex

    return mex



def solve():

    N = int(input())

    A = list(map(int, input().split()))



    xor_sum = 0

    for a in A:

        xor_sum ^= calculate_grundy(a)



    if xor_sum == 0:

        print("Bruno")

    else:

        print("Anna")



