import java.io.*;

import java.util.*;

import java.util.function.*;

import java.util.stream.*;



public class Main {

    public static void main(String[] args) throws Exception {

        Scanner sc = new Scanner();

        int n = sc.nextInt();

        int ans = 0;

        while (n-- > 0) {

            int x = sc.nextInt();

            int current = 0;

            for (int i = 2; i <= Math.sqrt(x); i++) {

                while (x % i == 0) {

                    current++;

                    x /= i;

                }

            }

            if (x > 1) {

                current++;

            }

            ans ^= current;

        }

        System.out.println(ans == 0 ? "Bruno" : "Anna");

    }

}



