import java.util.*;



class Main {

 public static long tree[];



 public static void init(int n) {

  tree = new long[4 * n];

 }



 public static long buildST(int arr[], int i, int start, int end) {

  if (start == end) { // leaf node case

   tree[i] = arr[start];

   return arr[start];

  }

  int mid = (start + end) / 2;

  buildST(arr, 2 * i + 1, start, mid); // left subtree => 2*i+1

  buildST(arr, 2 * i + 2, mid + 1, end); // right subtree => 2*i+2

  tree[i] = tree[2 * i + 1] + tree[2 * i + 2];

  return tree[i];

 }



 public static long getSum(int arr[], int qi, int qj) {

  int n = arr.length;

  return getSumUtil(0, 0, n - 1, qi, qj);

 }



 public static long getSumUtil(int i, int si, int sj, int qi, int qj) {

  if (qj < si || qi > sj) { // non-overlapping

   return 0;

  } else if (si >= qi && sj <= qj) { // complete overlap

   return tree[i];

  } else { // partrial overlap

   int mid = (si + sj) / 2;

   long left = getSumUtil(2 * i + 1, si, mid, qi, qj);

   long right = getSumUtil(2 * i + 2, mid + 1, sj, qi, qj);

   return left + right;

  }

 }



 public static void update(int arr[], int idx, int newVal) {

  int n = arr.length;

  int diff = newVal - arr[idx];

  arr[idx] = newVal;

  updateUtil(0, 0, n - 1, idx, diff); // segment tree updation

 }



 public static void updateUtil(int i, int si, int sj, int idx, int diff) { // O(log n)

  if (idx > sj || idx < si) {

   return;

  }

  tree[i] += diff;

  if (si != sj) { // non-leaf

   int mid = (si + sj) / 2;

   updateUtil(2 * i + 1, si, mid, idx, diff); // left

   updateUtil(2 * i + 2, mid + 1, sj, idx, diff); // right

  }

 }



 public static void main(String args[]) {

  Scanner sc = new Scanner(System.in);

  int n = sc.nextInt(), a[] = new int[n], b[] = new int[n];

  // long psa[] = new long[n];

  for (int i = 0; i < n; i++) {

   a[i] = sc.nextInt();

   // if (i > 0) {

   // psa[i] = psa[i - 1] + a[i];

   // } else {

   // psa[i] = a[i];

   // }

  }



  //

  init(n);

  buildST(a, 0, 0, n - 1);

  //



  int nextb[] = new int[n];

  for (int i = 0; i < n; i++) {

   b[i] = sc.nextInt();

  }

  nextb[n - 1] = n;

  for (int i = n - 2; i >= 0; i--) {

   if (b[i + 1] > 1) {

    nextb[i] = i + 1;

   } else {

    nextb[i] = nextb[i + 1];

   }

  }

  int q = sc.nextInt();

  while (q-- > 0) {

