def check_bipartite(n, links):
    """
    links[u] = { v1, v2, ... } のグラフが二部グラフであるかどうかを確認する。
    """
    color = [-1] * n
    for s in range(n):
        if color[s] != -1:
            continue
        q = [s]
        color[s] = 0
        while q:
            u = q.pop()
            cu = color[u]
            cv = cu ^ 1
            for v in links[u]:
                if color[v] == -1:
                    color[v] = cv
                    q.append(v)
                elif color[v] == cu:
                    return False
    return True


