    global MOD
    n, MOD = map(int, input().split())

    f = [[0] * (n + 5) for _ in range(n + 5)]
    g = [0] * (n + 5)
    h = [0] * (n + 5)

    h[0] = 1
    g[0] = 1

    for i in range(1, n + 1):
        for j in range(1, i + 1):
