    public static int bin1(int[] arr, long val) {
        int st = 0;
        int len = arr.length-1;
        int end = len;
        while (st <= end) {
            int mid = st + (end - st) / 2;
            if (arr[mid]<=val) {
                st = mid + 1;
            }
            else {
                end = mid - 1;
            }
        }
        return end;
    }
}

