import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        StringBuilder output = new StringBuilder();
        // ここから
        int n = sc.nextInt(), q = sc.nextInt();
        int[] a = new int[n], b = new int[n], randnum = new int[n], suma = new int[n + 1], sumb = new int[n + 1];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
            a[i]--;
        }
        for (int i = 0; i < n; i++) {
            b[i] = sc.nextInt();
            b[i]--;
        }
        int mod = 998244353;
        for (int i = 0; i < n; i++) {
            randnum[i] = new Random().nextInt(mod);
        }

        for (int i = 0; i < n; i++) {
            suma[i + 1] = (suma[i] + randnum[a[i]]) % mod;
            sumb[i + 1] = (sumb[i] + randnum[b[i]]) % mod;
        }
        for (int i = 0; i < q; i++) {
            int l1 = sc.nextInt(), r1 = sc.nextInt(), l2 = sc.nextInt(), r2 = sc.nextInt();
            if ((suma[r1] - suma[l1 - 1] + mod) % mod == (sumb[r2] - sumb[l2 - 1] + mod) % mod)
                output.append("Yes");
            else
                output.append("No");
            if (i < q - 1)
                output.append("\n");
        }

        // ここまで
        System.out.println(output);
        sc.close();
    }
}

