            p[i] = sc.nextInt();
            v[i] = sc.nextInt();
        }

        boolean[] left = new boolean[q];
        boolean[] right = new boolean[q];
        Arrays.fill(left, true);
        Arrays.fill(right, true);
        for(int i =0 ; i < q ; i++){
            for(int j = i+1; j <q; j++){
