        int n = sc.nextInt();
        int d = sc.nextInt();

        int[] xArr = new int[n+1];
        int[] yArr = new int[n+1];
        long xsum = 0L;
        long ysum = 0L;
        for (int i = 0; i < n; i++) {
        	xArr[i] = sc.nextInt();
        	yArr[i] = sc.nextInt();
        	xsum += xArr[i];
        	ysum +=  yArr[i];
		}
		sc.close();

		xArr[n] = Integer.MAX_VALUE;
		yArr[n] = Integer.MAX_VALUE;
		Arrays.sort(xArr);
		Arrays.sort(yArr);

		long[] xDist = new long[4*MAXD+1];
		xDist[0] = 2L*MAXD * n + xsum;

		int xi = 0;
		for (int i = 1; i < xDist.length; i++) {
			while(xi < n && xArr[xi] < i - 2*MAXD) xi++;
			xDist[i] = xDist[i-1] - (n - 2 * xi);
//			System.out.println(xDist[i]);
		}

		long[] yDist = new long[4*MAXD+1];
