			while(yi < n && yArr[yi] < i  - 2*MAXD) yi++;
			yDist[i] = yDist[i-1] - (n - 2 * yi);
//			System.out.println(yDist[i]);
		}
		Arrays.sort(xDist);
		Arrays.sort(yDist);

        long ans = 0L;
        int yj = yDist.length-1;
