import java.io.PrintWriter;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {

        var sc = new Scanner(System.in);
        var pw = new PrintWriter(System.out);

        int T = Integer.parseInt(sc.next());
        for(int t = 0; t < T; t++){
            int n = Integer.parseInt(sc.next());
            var p = new int[n+1];
            for(int i = 1; i <= n; i++){
                p[i] = Integer.parseInt(sc.next());
            }

            int count = 0;
            for(int i = 1; i <= n; i++){
                if(p[i] == i){
                    count++;
                }
            }
            if(count == n){
                pw.println(0);
                continue;
            }

            var maxL = new int[n+1];
            for(int i = 2; i <= n; i++){
                maxL[i] = Math.max(p[i-1], maxL[i-1]);
            }

            boolean ok = false;
            for(int i = 1; i <= n; i++){
                if(p[i] == i && maxL[i] < i){
                    ok = true;
                    break;
                }
            }
            if(ok){
                pw.println(1);
                continue;
            }

            if(p[1] == n && p[n] == 1){
                pw.println(3);
            }else{
                pw.println(2);
            }
        }
        pw.flush();
    }
}

