import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    int N = scanner.nextInt();
    char[] s = scanner.next().toCharArray();
    int[] S = new int[N];
    String rps = "RPS";
    for (int i = 0; i < s.length; i++) S[i] = rps.indexOf(s[i]);

    int[][] dp = new int[N + 1][3];
    for (int i = 1; i <= N; i++) {
      int e = S[i - 1]; // even
      int w = (e + 1) % 3; // win
      int l = (e + 2) % 3; // lose
      dp[i][e] = Math.max(dp[i - 1][l], dp[i - 1][w]);
      dp[i][w] = Math.max(dp[i - 1][e], dp[i - 1][l]) + 1;
      dp[i][l] = -1;
    }
    System.out.println(Math.max(Math.max(dp[N][0], dp[N][1]), dp[N][2]));
  }
}

