import java.util.StringTokenizer;

public class Main {
    private static BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
    private static BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(System.out));
    private static StringTokenizer st;

    public static void main(String[] args) throws IOException {
        st = new StringTokenizer(reader.readLine());
        int N = Integer.parseInt(st.nextToken());
        st = new StringTokenizer(reader.readLine());
        int[] A = new int[N];
        for (int i = 0; i < N; i++) {
            A[i] = Integer.parseInt(st.nextToken());
        }
        long result = 0;
        for (int i = 0; i <= 30; i++) {
            boolean[] present = new boolean[N];
            for (int j = 0; j < N; j++) {
                present[j] = (A[j] & (1 << i)) != 0;
            }
            boolean[] totalNumberOdd = new boolean[N + 1];
            int odds = 0;
            int evens = 0;
            for (int j = 1; j <= N; j++) {
                totalNumberOdd[j] = totalNumberOdd[j - 1] ^ present[j - 1];
                if (totalNumberOdd[j]) {
                    odds++;
                } else {
                    evens++;
                }
            }
            long timesInResult = 0;
            int oddsBefore = 0;
            int evensBefore = 0;
            for (int start = 0; start < N - 1; start++) {
                if (totalNumberOdd[start + 1]) {
                    oddsBefore++;
                } else {
                    evensBefore++;
                }
                if (totalNumberOdd[start]) {
                    timesInResult += evens - evensBefore;
                } else {
                    timesInResult += odds - oddsBefore;
                }
            }
            result += timesInResult * (1 << i);
        }
        System.out.println(result);
    }
}

