				o.tx = t;
				t = o.sy;
				o.sy = o.ty;
				o.ty = t;
			}
			o.ans = o.tx - o.sx;
			arr[i] = o;
			que1.add(o);
		}
		br.close();

		PriorityQueue<Query> que2 = new PriorityQueue<>((o1, o2) -> o1.tx - o2.tx);
		TreeMap<Integer, Obj> map = new TreeMap<>();
		for (int i = 0; i < n; i++) {
