			Integer[] ks = hm.keySet().toArray(new Integer[0]);
			for (Integer k : ks) {
				Obj o = hm.get(k);
				o.cost += l[i] - k;
				o.y = l[i];
				if (map.containsKey(l[i])) {
					Obj o1 = o;
					Obj o2 = map.get(l[i]);
