						map.put(u[i], o);
					}
					for (int e : o1.set) {
						Query qr = arr[e];
						qr.ans += o1.cost - qr.oc;
						qr.oc = o2.cost;
						qr.o = o2;
					}
					o2.set.addAll(o1.set);
				} else {
					map.put(u[i], o);
				}
			}
