				Query qr = que1.peek();
				if (qr.sx > i) {
					break;
				}
				que1.poll();
				if (map.containsKey(qr.sy)) {
					Obj o = map.get(qr.sy);
					qr.oc = o.cost;
					qr.o = o;
					o.set.add(qr.i);
