public class Main {
	public static void main(String[] args) {
		var sc = new Scanner(System.in);
		var n = sc.nextInt();
		var k = sc.nextInt();
		sc.close();

		var mc = new Main().new ModCalc();
		var n2 = mc.multiply(n, n);
		var a = mc.divide(mc.add(mc.subtract(n2, mc.multiply(n, 2)), 2), n2);
		var b = mc.divide(2, n2);

		var dp = new int[k][2];
		dp[0][0] = a;
		dp[0][1] = b;
		for (var i = 0; i < k - 1; i++) {
			dp[i + 1][0] = mc.add(mc.multiply(dp[i][0], a), mc.multiply(dp[i][1], b, (n - 1)));
			dp[i + 1][1] = mc.add(mc.add(mc.multiply(dp[i][1], a), mc.multiply(dp[i][0], b)), mc.multiply(dp[i][1], b, (n - 2)));
		}

		var v1 = dp[k - 1][0];
		var v2 = mc.multiply(dp[k - 1][1], (mc.subtract(mc.divide(mc.multiply(n, n + 1),  2), 1)));
		var result = mc.add(v1, v2);
		System.out.println(result);
	}

	public class ModCalc {
		private int mod = 998244353;

		public ModCalc() {
		}

		public ModCalc(int mod) {
			this.mod = mod;
		}

		public int add(int a, int b) {
			return (int) (((long) a + b) % mod);
		}

		public int subtract(int a, int b) {
			return add((int) (((long) a - b) % mod), mod);
		}

		public int multiply(int a, int b) {
			return add((int) (((long) a * b) % mod), mod);
		}

		public int multiply(int... a) {
			int result = 1;
			for (var a1 : a) {
				result = multiply(result, a1);
			}
			return result;
		}

		public int divide(int a, int b) {
			return multiply(a, pow(b, mod - 2));
		}

		public int pow(int n, int k) {
			if (k == 0) {
				return 1;
			} else if (k % 2 == 0) {
				int p = pow(n, k / 2);
				return multiply(p, p);
			} else {
				int p = pow(n, (k - 1) / 2);
				return multiply(multiply(p, p), n);
			}
		}

		public int combine(int n, int k) {
			int sum1 = 1;
			int sum2 = 1;
			for (int i = 0; i < k; i++) {
				sum1 = multiply(sum1, n - i);
				sum2 = multiply(sum2, i + 1);
			}
			return divide(sum1, sum2);
		}

		public int factorial(int n) {
			int result = 1;
			for (int i = 0; i < n; i++) {
				result = multiply(result, i + 1);
			}
			return result;
		}

		public int[][] combines(int n) {
			var factorials = factorials(n);
			var combines = new int[n + 1][n + 1];
			for (var i = 0; i <= n; i++) {
				int sum = 1;
				combines[i][0] = 1;
				for (var j = 1; j <= i; j++) {
					sum = multiply(sum, i + 1 - j);
					combines[i][j] = divide(sum, factorials[j]);
				}
			}
			return combines;
		}

		public int[] factorials(int n) {
			var factorials = new int[n + 1];
			factorials[0] = 1;
			for (var i = 1; i <= n; i++) {
				factorials[i] = multiply(factorials[i - 1], i);
			}
			return factorials;
		}
	}
