    public static Map<Integer, long[]> dfs(int u, int fa, int depth) {

        Map<Integer, long[]> map = new HashMap<>();

        map.put(color[u], new long[]{depth, 1});

        for (int v : edges[u]) {

            if (v == fa) continue;

            Map<Integer, long[]> map2 = dfs(v, u, depth+1);

