import java.util.*;

import java.util.Map.Entry;

import java.io.*;

import java.math.BigInteger;

import java.nio.charset.StandardCharsets;



public class Main {



	public static void main(String[] args) throws IOException {

		InputStreamReader reader = new InputStreamReader(System.in, StandardCharsets.UTF_8);

		BufferedReader in = new BufferedReader(reader);

		Main ins = new Main(in);

		ins.calc();

		ins.showResult();

	}



	static class Node {

		int id;

		int gid = -1;

		int reachNum = -1;

		Node next;

		Map<Integer, Node> prevs;



		Node(int id) {

			this.id = id;

			this.prevs = new TreeMap<>();

			this.next = null;

		}



		int getReachNum() {

			if (this.reachNum > 0) {

				return this.reachNum;

			} else {

				int nextReachNum = this.next.getReachNum();

				this.reachNum = nextReachNum + 1;

				return this.reachNum;

			}

		}

	}



	PrintWriter writer = new PrintWriter(System.out);

	BufferedReader in;

	int N;

	int[] a;

	Node[] nodes;



	Main(BufferedReader in) throws IOException {

		this.N = Integer.parseInt(in.readLine());

		this.a = new int[N];

		String[] tokens = in.readLine().split(" ");

		for (int i = 0; i < N; ++i) {

			a[i] = Integer.parseInt(tokens[i]) - 1;

		}

		this.nodes = new Node[N];

		for (int i = 0; i < N; ++i) {

			this.nodes[i] = new Node(i);

		}

		for (int i = 0; i < N; ++i) {

			Node from = this.nodes[i];

			Node to = this.nodes[a[i]];

			from.next = to;

			to.prevs.put(from.id, from);

		}

	}



	void mark(Node node, int gid) {

		if (node.gid >= 0) {

			return;

		}

		node.gid = gid;

		mark(node.next, gid);

	}



	void calc() {

		// まずループのみにする

		Deque<Node> deque = new ArrayDeque<>();

		for (Node node : nodes) {

			if (node.prevs.isEmpty()) {

				deque.add(node);

			}

		}

		while (!deque.isEmpty()) {

			Node node = deque.pollFirst();

			node.next.prevs.remove(node.id);

			if (node.next.prevs.isEmpty()) {

				deque.addLast(node.next);

			}

		}



		// ループのみになった

		// gidを振る

		int gid = 0;

		for (Node node : nodes) {

			if ((node.gid < 0) && !node.prevs.isEmpty()) {

				mark(node, gid);

				++gid;

			}

		}

		// gidごとのcountをする

		int[] gidCounts = new int[gid];

		Arrays.fill(gidCounts, 0);

		for (Node node : nodes) {

			if (node.gid >= 0) {

				gidCounts[node.gid]++;

			}

		}

		// ループの到達可能をmarkする

		for (Node node : nodes) {

			if (node.gid >= 0) {

				node.reachNum = gidCounts[node.gid];

			}

		}

		long result = 0L;

		for (Node node : nodes) {

			result += (long) node.getReachNum();

		}

		this.writer.println(result);



	}



	void showResult() {

		this.writer.flush();

	}



}

