public class Main {

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt(); // 鍵の本数

        int M = sc.nextInt(); // 試行回数

        int K = sc.nextInt(); // 必要な正しい鍵の本数



        int[][] A = new int[M][N];

        int[] C = new int[M];

        char[] R = new char[M];

        boolean[] testResult = new boolean[M];

        for (int i = 0; i < M; i++) {

            C[i] = sc.nextInt();

            for (int j = 0; j < C[i]; j++) {

                A[i][j] = sc.nextInt();

            }

            R[i] = sc.next().charAt(0);

            if (R[i] == 'o') {

                testResult[i] = true;

            } else {

                testResult[i] = false;

            }

        }

        sc.close();

        int ans = 0;

        for (int bit = 0; bit < 1 << N; bit++) {

            int match = 0;

            // 試行回数

            for (int i = 0; i < M; i++) {

                int openCnt = 0;

                boolean isOpen = false;

                // 鍵を挿し込む回数

                for (int j = 0; j < C[i]; j++) {

                    if ((bit & 1 << (A[i][j]-1)) != 0) {

                        openCnt++;

                    }



                }

                if (openCnt >= K) {

                    isOpen = true;

                } else {

                    isOpen = false;

                }

                if (isOpen == testResult[i]) {

                    match++;

                }

            }

            if (match == M) {

                ans++;

            }

        }

        System.out.println(ans);

    }



}

