			cc.add(-INF);

			cc.add(INF);



			TreeSet<Long> S = new TreeSet<Long>();

			TreeSet<Long> L = new TreeSet<Long>();

			TreeSet<Long> R = new TreeSet<Long>();

			S.add(INF);S.add(-INF);

			L.add(-INF);R.add(INF);

			FenwickTree d = new FenwickTree(cc.size()); 



