public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);

        // 入力1
        String str = scan.nextLine();
        String[] sp = str.split(" ");
        int n = Integer.valueOf(sp[0]);
        long x = Long.valueOf(sp[1]);
        long y = Long.valueOf(sp[2]);

        // 入力2
        int[] a = new int[n];
        String str2 = scan.nextLine();
        String[] sp2 = str2.split(" ");
        for (int i = 0 ; i < n ; i++) {
          a[i] = Integer.valueOf(sp2[i]);
        }

        // 入力3
        int[] b = new int[n];
        String str3 = scan.nextLine();
        String[] sp3 = str3.split(" ");
        for (int i = 0 ; i < n ; i++) {
          b[i] = Integer.valueOf(sp3[i]);
        }

        // 降順ソート
        Arrays.sort(a);
        for (int f = 0, l = a.length - 1; f < l; f++, l--){
          int temp = a[f];
          a[f]  = a[l];
          a[l] = temp;
        }

        Arrays.sort(b);
        for (int f = 0, l = b.length - 1; f < l; f++, l--){
          int temp = b[f];
          b[f]  = b[l];
          b[l] = temp;
        }

        // 初期化
        int sumA = countDishes(n, x, a);
        int sumB = countDishes(n, y, b);

        // 出力
        if (sumA <= sumB) {
          System.out.println(sumA);
        } else {
          System.out.println(sumB);
        }

        // System.out.println();
        scan.close();
    }

    public static int countDishes(int argN, long maxTaste, int[] arrTasts) {
      long sumTaste = 0;
      int sumDish = 0;
      for(int i = 0 ; i < argN ; i++) {
        // 限界超過
        if (sumTaste > maxTaste) {
          break;
        }

        // 加算
        sumTaste += arrTasts[i];
        sumDish ++;
      }

      return sumDish;
    }
}

