        int Y = Integer.parseInt(in[2]);
        int[][] mat = new int[H][W];
        boolean[][] visited = new boolean[H][W];

        PriorityQueue<Island> queue = new PriorityQueue<>(Island::compareTo);
        for (int y = 0; y < H; y++) {
            updateIn();
            for (int x = 0; x < W; x++) {
                mat[y][x] = Integer.parseInt(in[x]);
                if (y == 0 || y == H - 1 || x == 0 || x == W - 1) {
                    queue.add(new Island(x, y, mat[y][x]));
                    visited[y][x] = true;
                }
            }
        }

        int count = H * W;
        int[] offX = {-1, 1, 0, 0};
        int[] offY = {0, 0, -1, 1};

        for (int i = 1; i <= Y; i++) {
