import java.util.*;
import java.lang.*;
import java.io.*;

public class Main{

    public static void main(String[] args){
        Scanner scanner = new Scanner(System.in);
        int N = scanner.nextInt();
        int T = scanner.nextInt();
        int P = scanner.nextInt();

        ArrayList<Integer> list = new ArrayList<Integer>();
        int counts = 0;
        for(int i = 0; i < N ; i++){
          list.add(scanner.nextInt());
          if(list.get(i) >= T){
            counts++;
          }
        }

        if(counts >= P){
          System.out.print(0);
          return;
        }

        ArrayList<Integer> dayList = new ArrayList<Integer>();
        for(int i = 0 ; i < N ; i++){
          dayList.add(T - list.get(i));               //髪の毛がTになるまで残り何日必要か
        }

        Collections.sort(dayList);                    //小さい順に並べ替える

        System.out.println(dayList.get(P - 1));                  //P番目の数 = 条件を満たす日数

        scanner.close();
    }
}

