import java.io.*;
import java.util.*;

class TreeCenter {
    List<List<Integer>> g;
    int[] cnt;

    public int center (List<List<Integer>> g, int start, int nVertex) {
        this.g = g;
        cnt = new int[g.size()];
        return dfs(start, -1, nVertex);
    }

    private int dfs(int i, int p, int n) {
        cnt[i]=1;
        int max = 0;
        int sum = 1;
        for (Integer ch : g.get(i)) {
            if (ch == p) continue;
            int r = dfs(ch, i, n);
            if (r != -1) return r;
            cnt[i] += cnt[ch];
            sum += cnt[ch];
            max = Math.max(max, cnt[ch]);
        }
        max = Math.max(max, n - sum);
        if (max * 2 <= n) {
            return i;
        }
        return -1;
    }

}

public class Main implements Runnable {
    List<List<Integer>> g;
    TreeCenter center;
    public void solve() {
        int n = nextInt();
        g = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            g.add(new ArrayList<>());
        }
        for (int i = 0; i < n - 1; i++) {
            int u=nextInt()-1,v=nextInt()-1;
            g.get(u).add(v);
            g.get(v).add(u);
        }
        center = new TreeCenter();
        int v = center.center(g, 0, n);
        PriorityQueue<List<Integer>> q = new PriorityQueue<>(new Comparator<List<Integer>>() {
            @Override
            public int compare(List<Integer> o1, List<Integer> o2) {
                return -Integer.compare(o1.size(), o2.size());
            }
        });
        for (Integer ch : g.get(v)) {
            List<Integer> list = new ArrayList<>();
            dfs(ch, v, list);
            q.add(list);
        }
        while (!q.isEmpty()) {
            if (q.size() >= 2) {
                List<Integer> l1 = q.poll();
                List<Integer> l2 = q.poll();
                int r1=l1.remove(l1.size()-1)+1;
                int r2=l2.remove(l2.size()-1)+1;
                out.println(r1+" "+ r2);
                if (!l1.isEmpty()) {
                    q.add(l1);
                }
                if (!l2.isEmpty()) {
                    q.add(l2);
                }
            } else {
                List<Integer> list = q.poll();
                out.println((list.get(0)+1) + " " + (v+1));
            }
        }
    }

    void dfs(int i, int p, List<Integer> list) {
        list.add(i);
        for (Integer ch : g.get(i)) {
            if (ch == p) continue;
            dfs(ch, i, list);
        }
    }

    public static void main(String[] args) throws Exception {
        new Thread(null, new Main(), "CustomThread", 1024 * 1024 * 100).start();
    }

    @Override
    public void run() {
        int t = 1;
        for (int i = 0; i < t; i++) {
            new Main().solve();
        }
        out.flush();
    }

    static PrintWriter out = new PrintWriter(System.out, false);
    static InputReader in = new InputReader(System.in);
    static String next() { return in.next(); }
    static int nextInt() { return Integer.parseInt(in.next()); }
    static long nextLong() { return Long.parseLong(in.next()); }
    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }
    }
}

