import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int n=input.nextInt();
        var g=new long[n][2];
        var ans=new long[n];
        long sumL=0;
        long sumR=0;
        for(int i=0;i<n;++i){
           g[i][0]=input.nextInt();
           g[i][1]=input.nextInt();
           sumL+= g[i][0];
           sumR+= g[i][1];
           ans[i]=g[i][0];
        }
        input.close();
        if(sumL>0||sumR<0){
            System.out.println("No");
            return;
        }
        long sum=sumL;
        for(int i=0;i<n;++i){
            if(sum==0){
                break;
            }
            long d=Math.min(-1*sum, g[i][1]-g[i][0]);
            ans[i]+=d;
            sum+=d;
        }
        System.out.println("Yes");
        for(int i=0;i<n;++i){
            System.out.printf("%d ", ans[i]);
        }
    }
}

