        PriorityQueue<Pair>pq=new PriorityQueue<Pair>((x,y)->x.price-y.price);
        pq.add(new Pair(r, "Red"));
        pq.add(new Pair(g,"Green"));
        pq.add(new Pair(b,"Blue"));
