import java.util.*;

public class Main {
    static class Edge {
        int to;
        long weight;
        Edge(int to, long weight) {
            this.to = to;
            this.weight = weight;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read the number of vertices and edges
        int N = scanner.nextInt();
        int M = scanner.nextInt();

        // Read the weights of the vertices
        long[] vertexWeights = new long[N + 1];
        for (int i = 1; i <= N; i++) {
            vertexWeights[i] = scanner.nextLong();
        }

        // Create an adjacency list for the graph
        List<List<Edge>> graph = new ArrayList<>();
        for (int i = 0; i <= N; i++) {
            graph.add(new ArrayList<>());
        }

        // Read the edges of the graph
        for (int i = 0; i < M; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            long b = scanner.nextLong();
            graph.get(u).add(new Edge(v, b));
            graph.get(v).add(new Edge(u, b));
        }

        // Use Dijkstra's algorithm to find the shortest paths from vertex 1
        long[] dist = new long[N + 1];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[1] = vertexWeights[1];

        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[1]));
        pq.add(new long[]{1, vertexWeights[1]});

        while (!pq.isEmpty()) {
            long[] current = pq.poll();
            int node = (int) current[0];
            long d = current[1];

            if (d > dist[node]) continue;

            for (Edge edge : graph.get(node)) {
                int neighbor = edge.to;
                long newDist = dist[node] + vertexWeights[neighbor] + edge.weight;
                if (newDist < dist[neighbor]) {
                    dist[neighbor] = newDist;
                    pq.add(new long[]{neighbor, newDist});
                }
            }
        }

        // Output the result for vertices 2 to N
        for (int i = 2; i <= N; i++) {
            System.out.print(dist[i] + " ");
        }
    }
}

