                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }

    public static int gcd(int a, int b) {
        if (b == 0) return a;
        return gcd(b, a % b);
    }

    static class E {
        int t;
        long w;

        public E(int t, long w) {
            this.t = t;
            this.w = w;
        }
    }

    static ArrayList<E>[] adj;
    static boolean[] vis;
    static int fn;
    static long md;
    public static void dfs(int u, long d) {
        vis[u] = true;
        if (d > md) {
            md = d;
            fn = u;
        }

        for (E e : adj[u]) {
            if (!vis[e.t]) {
                dfs(e.t, d + e.w);
            }
        }
    }
    public static void main(String[] args) {
        FastReader sc = new FastReader();

        int n = sc.nextInt();
        adj = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) {
            adj[i] = new ArrayList<>();
        }

        long tes = 0;
        for (int i = 0; i < n - 1; i++) {
            int a = sc.nextInt();
            int b = sc.nextInt();
            long c = sc.nextLong();
            adj[a].add(new E(b, c));
            adj[b].add(new E(a, c));
            tes += c;
        }

        vis = new boolean[n + 1];
        md = 0;
        dfs(1, 0);

        vis = new boolean[n + 1];
        md = 0;
        dfs(fn, 0);
        long td = md;

        long mtd = 2 * tes - td;
        System.out.println(mtd);
    }


}

