import java.util.Scanner;



public class Main {

    public static void main(String[] args) {

        Scanner scanner = new Scanner(System.in);



        int n = scanner.nextInt();



        ArrayList<Integer> list = new ArrayList<>();



        for (int i = 0; i < n; i++) {

            int exponent = scanner.nextInt();  // 直接指数を読み込む

            while (!list.isEmpty() && list.get(list.size() - 1) == exponent) {

                list.remove(list.size() - 1);  // 右から2つのボールを取り除く

                exponent++;  // 大きさが合計された新しいボールの指数を計算

            }

            list.add(exponent);  // 新しいボールを追加

