public class Main {

    static Scanner sc = new Scanner(System.in);

    static final int N = 400010;

    static long[] C = new long[N<<2];

    static int[] cnt = new int[N<<2];



    public static void insert(int l, int r, int o, int p, int x){

        if(l == r){

            C[o] += (long)x;

            ++cnt[o];

            return;

        }

        int mid = l + r >> 1;

        if(p <= mid) insert(l, mid, o<<1, p, x);

        else insert(mid+1, r, o<<1|1, p, x);

        C[o] = C[o<<1] + C[o<<1|1];

        cnt[o] = cnt[o<<1] + cnt[o<<1|1];

    }



    public static long query1(int al, int ar, int l, int r, int o){

        if(al <= l && ar >= r)

            return C[o];

        int mid = l + r >> 1;

        long ret = 0;

        if(al <= mid) ret = query1(al, ar, l, mid ,o<<1);

        if(ar > mid) ret += query1(al, ar, mid+1, r, o<<1|1);

        return ret;

    }

    public static int query2(int al, int ar, int l, int r, int o){

        if(al <= l && ar >= r)

            return cnt[o];

        int mid = l + r >> 1;

        int ret = 0;

        if(al <= mid) ret = query2(al, ar, l, mid ,o<<1);

        if(ar > mid) ret += query2(al, ar, mid+1, r, o<<1|1);

        return ret;

    }



    static ArrayList<Integer> A = new ArrayList<>();

    static HashMap<Integer, Integer> m = new HashMap<>();

    static int[] B = new int[N];

    public static void main(String[] args) {

        int n = sc.nextInt();

        for(int i = 0; i < n; i++){

            B[i] = sc.nextInt();

            A.add(B[i]);

        }

        Collections.sort(A);

        int ind = 0, las = -1;

        for(int x: A){

            if(x == las) continue;

            m.put(x, ++ind);

            las = x;

        }

        long ans = 0;

        for(int i = 0; i < n; i++){

            long s = query1(1, m.get(B[i]), 1, ind, 1);

            int c = query2(1, m.get(B[i]), 1, ind, 1);

            ans += (long)c * B[i] - s;

            insert(1, ind, 1, m.get(B[i]), B[i]);

        }

        System.out.println(ans);

    }

}

