import java.util.Scanner;



public class Main {

    public static void main(String[] args) {

        Scanner scanner = new Scanner(System.in);

        int N = scanner.nextInt(); // 歯の数

        int Q = scanner.nextInt(); // 治療の回数

        int[] teeth = new int[N + 1]; // 各穴の歯が生えているかどうかを示す配列



        // 初期状態で歯が生えている穴の数を記録

        int initialTeeth = N;



        // 初期状態で各穴に歯が生えているかどうかを記録

        for (int i = 1; i <= N; i++) {

            teeth[i] = 1; // 歯が生えている

        }



        // 治療の実行

        for (int i = 0; i < Q; i++) {

            int T = scanner.nextInt(); // 治療する穴の番号

            if (teeth[T] == 1) {

                // 歯が生えている場合、歯を抜く

                teeth[T] = 0;

                initialTeeth--; // 歯が抜かれたので歯の総数を減らす

            } else {

                // 歯が生えていない場合、歯を生やす

                teeth[T] = 1;

                initialTeeth++; // 歯が生えたので歯の総数を増やす

            }

        }



        scanner.close();



        System.out.println(initialTeeth); // 最終的な歯の総数を出力

    }

}

