import java.util.ArrayList;

import java.util.List;

import java.util.Scanner;



public class Main {



  public static void main(String[] args) {

    try (Scanner sc = new Scanner(System.in)) {

      long L = sc.nextLong();

      long R = sc.nextLong();



      long target = L;

      List<Long> sequenceList = new ArrayList<>();

      while (true) {

        long[] factors = factorization(target, R);

        sequenceList.add(target);

        target = factors[0] * (factors[1] + 1);

        sequenceList.add(target);

        if (target == R) {

          break;

        }

      }



      Long[] sequences = sequenceList.toArray(new Long[0]);

      System.out.println(sequences.length / 2);

      for (int i = 0; i < sequences.length; i += 2) {

        System.out.println(sequences[i] + " " + sequences[i + 1]);

      }

    }

  }



  public static long[] factorization(long target, long max) {

    long factor1 = 1;

    long factor2 = target;

    while (true) {

      if (factor1 * (factor2 + 1) == max) {

        break;

      }

      if (factor1 * (factor2 + 1) > max) {

        factor1 /= 2;

        factor2 *= 2;

        break;

      }

      if (factor2 % 2 != 0) {

        break;

      }

      factor1 *= 2;

      factor2 /= 2;

    }

    return new long[] { factor1, factor2 };

  }

}

