			long M = Long.parseLong(sc.next());

			long[] A = new long[N];

			for(int i = 0; i < N; i++) A[i] = Long.parseLong(sc.next());



			long m = M;

			List<Long> ps = new ArrayList<Long>();

			for(long i = 2; i * i <= m; i++) {

				if(m % i != 0) continue;

				long p = 1;

				while(m % i == 0) {

					m /= i;

					p *= i;

				}

				ps.add(p);

			}

			if(m != 1) ps.add(m);



			int n = ps.size();

			int[] c = new int[1 << n];

			final long mod = 998244353;



			for(long a : A) {

				if(M % a != 0) continue;

				int mask = 0;

				for(int i = 0; i < n; i++) {

					if(a % ps.get(i) == 0) mask |= 1 << i;

				}

				c[mask] += 1;

			}



			long ans = M == 1 ? -1 : 0;

			for(int mask = 0; mask < 1 << n; mask++) {

				long p = (n - Integer.bitCount(mask)) % 2 == 1 ? -1 : 1;

				long x = 0;

				for(int sub = 0; sub < 1 << n; sub++) {

					if((mask & sub) == sub) {

						x += c[sub];

					}

				}

				ans += p * pow(2, x, mod);

				ans += mod;

				ans %= mod;

			}



			System.out.println(ans);

		}

	}



	static long pow(long a, long b, long mod) {

		long res = 1;

		while(b > 0) {

			if((b & 1) > 0) {

				res *= a;

				res %= mod;

			}

			a *= a;

			a %= mod;

			b >>= 1;

		}

		return res;

	}

}

