public class Main {



  public static void main(String[] args) {

    resolve(System.in, System.out);

  }



  static void resolve(InputStream is, PrintStream pw) {

    FastScanner sc = new FastScanner(new Scanner(is));

    int h = sc.nextInt();

    int w = sc.nextInt();

    char[][] grid = new char[h + 1][w + 1];

    Point[][] points = new Point[h + 1][w + 1];

    Point start = null;

    Point goal = null;

    Integer[][] energy = new Integer[h + 1][w + 1];

    for (int i = 1; i <= h; i++) {

      String row = sc.nextString();

      for (int j = 1; j <= w; j++) {

        grid[i][j] = row.charAt(j - 1);

        points[i][j] = new Point(i, j);

        if (grid[i][j] == 'S') {

          start = points[i][j];

        } else if (grid[i][j] == 'T') {

          goal = points[i][j];

        }

      }

    }

    int n = sc.nextInt();

    for (int i = 0; i < n; i++) {

      int r = sc.nextInt();

      int c = sc.nextInt();

      int e = sc.nextInt();

      energy[r][c] = e;

    }



    Integer[][] visit = new Integer[h + 1][w + 1];

    LinkedList<Step> bfs = new LinkedList<>();

    bfs.add(new Step(start, 0));

    while (!bfs.isEmpty()) {

      Step step = bfs.poll();

      Point point = step.point;

      int i = point.i;

      int j = point.j;

      int e = step.energy;

      if (grid[i][j] == '#') {

        continue;

      }

      if (energy[i][j] != null && e < energy[i][j]) {

        e = energy[i][j];

      }

      if (visit[i][j] != null && e <= visit[i][j]) {

        continue;

      }

      visit[i][j] = e;

      if (point.equals(goal)) {

        pw.println("Yes");

        return;

      }

      if (e == 0) {

        continue;

      }

      if (i - 1 >= 1) {

        bfs.add(new Step(points[i - 1][j], e - 1));

      }

      if (i + 1 <= h) {

        bfs.add(new Step(points[i + 1][j], e - 1));

      }

      if (j - 1 >= 1) {

        bfs.add(new Step(points[i][j - 1], e - 1));

      }

      if (j + 1 <= w) {

        bfs.add(new Step(points[i][j + 1], e - 1));

      }

    }

    pw.println("No");

  }



  static class Step {



    final Point point;

    final int energy;



    public Step(Point point, int energy) {

      this.point = point;

      this.energy = energy;

    }



    @Override

    public String toString() {

      return point + ": " + energy;

    }

  }



  static class Point {



    final int i;

    final int j;



    public Point(int i, int j) {

      this.i = i;

      this.j = j;

    }



    @Override

    public String toString() {

      return "(" + i + ", " + j + ")";

    }

  }



