        int[] b = new int[n];

        for(int i=0; i<n; i++) {

            a[i] = sc.nextInt();

            b[i] = sc.nextInt();

        }

        List<Integer> list = new ArrayList<>();

        for(int i=0; i<n; i++) {

            for(int j=i+1; j<n; j++) {

                if(a[i]==a[j] || b[i]==b[j]) {

