def bfs(si, sj, ti, tj, color):

    dist = [[inf] * N for _ in range(N)]

    dist[si][sj] = 0

    dq = deque([(si, sj)])

    while dq:

        i, j = dq.popleft()

        for di, dj in [[0, 1], [1, 0], [0, -1], [-1, 0]]:

            ni, nj = i + di, j + dj

            if not ni in range(N) or not nj in range(N):

                continue

            if c[ni][nj] == color:

                if dist[ni][nj] > dist[i][j]:

