		for (int i = 0; i < n; i++) {

			Arrays.fill(d[i], -1);

		}

		d[0][0] = 0;

		Deque<Integer> que = new ArrayDeque<>();

		que.add(0);

		while (!que.isEmpty()) {

			int cur = que.poll();

			int cx = cur / n;

			int cy = cur % n;

			for (int i = 0; i < 4; i++) {

				int nx = cx + dx[i];

				int ny = cy + dy[i];

				if (nx < 0 || n <= nx || ny < 0 || n <= ny) {

