				int next = nx * n + ny;

				if (d[nx][ny] == -1) {

					if (s[nx][ny] == 'R') {

						que.addFirst(next);

						d[nx][ny] = d[cx][cy];

					} else {

						que.addLast(next);

						d[nx][ny] = d[cx][cy] + 1;

					}

				}

			}

		}

		int dr = d[n - 1][n - 1];



		d = new int[n][n];

		for (int i = 0; i < n; i++) {

			Arrays.fill(d[i], -1);

		}

		d[0][n - 1] = 0;

		que = new ArrayDeque<>();

		que.add(n - 1);

		while (!que.isEmpty()) {

			int cur = que.poll();

			int cx = cur / n;

			int cy = cur % n;

			for (int i = 0; i < 4; i++) {

				int nx = cx + dx[i];

				int ny = cy + dy[i];

