        BufferedReader br;

        StringTokenizer st;



        // Constructor to initialize the input reader

        public FastReader() {

            br = new BufferedReader(new InputStreamReader(System.in));

        }



        // Read the next word from input

        String next() {

            // Check if the current token exists, if not read a new line

            while (st == null || !st.hasMoreTokens()) {

                try {

                    st = new StringTokenizer(br.readLine());

                } catch (IOException e) {

                    e.printStackTrace();

                }

            }

            return st.nextToken();

        }



        // Read the next integer from input

        int nextInt() {

            return Integer.parseInt(next());

        }



        // Read the next long from input

        long nextLong() {

            return Long.parseLong(next());

        }



        // Read the next double from input

        double nextDouble() {

            return Double.parseDouble(next());

        }



        // Read the next line from input

        String nextLine() {

            String str = "";

            try {

                str = br.readLine().trim();

            } catch (Exception e) {

                e.printStackTrace();

            }

            return str;

        }

    }



    // Define a class to write output data quickly

    static class FastWriter {

        private final BufferedWriter bw;



        // Constructor to initialize the output writer

        public FastWriter() {

            this.bw = new BufferedWriter(new OutputStreamWriter(System.out));

        }



        // Print the given object to the output

        public void print(Object object) throws IOException {

            bw.append("" + object);

        }



        // Print the given object to the output with a newline

        public void println(Object object) throws IOException {

            print(object);

            bw.append("\n");

        }



        // Close the output stream

        public void close() throws IOException {

            bw.close();

        }



        public void flush() throws IOException {

            bw.flush();

        }

    }



    public static void main(String[] args) throws IOException {

        try {

            FastReader in = new FastReader();

