        StringBuilder stb = new StringBuilder();



        for( int i = 0 ; i < N ; i++ ){

            stb.append( list.get(i));

        }



        return stb.toString();

    }



    public static String[] arrayString(String str, String s){



        String[] array = str.split(s);

        return array;

    }





    //標準入力をint型配列に置換

