        int N = str.length;

        int[] array = new int[N];

        for( int i = 0 ; i < N ; i++){

            array[i] = Integer.parseInt(str[i]);

        }

        return array;

    }



    //標準入力をLong型配列に置換

    public static long[] StringToLongArray(String[] str){



