    public static void graph(Map<Integer, List<Integer>> map, int v, int u){



        if( !map.containsKey(v)){

            List<Integer> li = new ArrayList<>();

            li.add(u);

            map.put(v, li);

        }else{

            List<Integer> li = map.get(v);

            li.add(u);

            map.put(v, li);

        }

    }



}

