import java.util.*;

import java.util.Map.Entry;

import java.io.*;

import java.math.BigInteger;

import java.nio.charset.StandardCharsets;



public class Main {



	public static void main(String[] args) throws IOException {

		InputStreamReader reader = new InputStreamReader(System.in, StandardCharsets.UTF_8);

		BufferedReader in = new BufferedReader(reader);

		Main ins = new Main(in);

		ins.calc();

		ins.showResult();

	}



	static class Cond {

		int a, b, c;



		Cond(int a, int b, int c) {

			this.a = a;

			this.b = b;

			this.c = c;

		}

	}



	PrintWriter writer = new PrintWriter(System.out);

	BufferedReader in;

	int N, M;

	Cond[] conds;

	List<int[]> results;



	Main(BufferedReader in) throws IOException {

		String[] tokens = in.readLine().split(" ");

		this.N = Integer.parseInt(tokens[0]);

		this.M = Integer.parseInt(tokens[1]);

		this.conds = new Cond[M];

		for (int i = 0; i < M; ++i) {

			tokens = in.readLine().split(" ");

			int a = Integer.parseInt(tokens[0]);

			int b = Integer.parseInt(tokens[1]);

			int c = Integer.parseInt(tokens[2]);

			this.conds[i] = new Cond(a, b, c);

		}

		this.results = new ArrayList<>();

	}



	void search(int condIndex, int[] state) {

		if (condIndex >= this.conds.length) {

			// 最後まできた→記録する

			int[] array = Arrays.copyOf(state, state.length);

			this.results.add(array);

			return;

		}

		Cond cond = this.conds[condIndex];

		int a = cond.a;

		int b = cond.b;

		int c = cond.c;

		int aOrder = -1;

		int bOrder = -1;

		for (int i = 0; i < N; ++i) {

			if (state[i] == a) {

				aOrder = i;

			} else if (state[i] == b) {

				bOrder = i;

			}

		}



		if (aOrder < 0 && bOrder < 0) {

			for (int i = 0; i + c < N; ++i) {

				int latter = i;

				int later = i + c;

				if (state[latter] < 0 && state[later] < 0) {

					// これはいける

					state[latter] = b;

					state[later] = a;

					search(condIndex + 1, state);

					state[latter] = -1;

					state[later] = -1;

				}

			}

		} else if (aOrder >= 0 && bOrder >= 0) {

			if (Math.abs(aOrder - bOrder) == c) {

				// そのまま行く

				search(condIndex + 1, state);

			}

		} else if (aOrder < 0) {

			// 後ろにいる方が未定

			int later = bOrder + c;

			if (later >= 0 && later < N) {

				if (state[later] < 0) {

					// 行ける

					state[later] = a;

					search(condIndex + 1, state);

					state[later] = -1;

				}

			}

		} else {

			// 前にいる方が未定

			int latter = aOrder - c;

			if (latter >= 0 && latter < N) {

				if (state[latter] < 0) {

					// 行ける

					state[latter] = b;

					search(condIndex + 1, state);

					state[latter] = -1;

				}

			}

		}

	}



	Map<Integer, Integer> conv(int[] state) {

		TreeSet<Integer> ids = new TreeSet<>();

		TreeSet<Integer> orders = new TreeSet<>();

		for (int i = 1; i <= N; ++i) {

			ids.add(i);

			orders.add(i);

		}

		TreeMap<Integer, Integer> map = new TreeMap<>();

		for (int i = 0; i < state.length; ++i) {

			if (state[i] < 0) {

				continue;

			}

			int id = state[i];

			int order = i + 1;

			map.put(id, order);

			ids.remove(id);

			orders.remove(order);

		}

		if (ids.size() == 1) {

			map.put(ids.first(), orders.first());

		} else {

			for (Integer id : ids) {

				map.put(id, -1);

			}

		}

		return map;

	}



	void show(int[] state) {

		for (int i = 0; i < state.length; ++i) {

			System.out.print(" " + state[i]);

		}

		System.out.println("");

	}



	void calc() {

		int[] state = new int[N];

		Arrays.fill(state, -1);

		search(0, state);

//		System.out.println(this.results.size());

//		for (int[] r : this.results) {

//			show(r);

//		}



		List<Map<Integer, Integer>> list = new ArrayList<>();

		for (int[] r : this.results) {

			list.add(this.conv(r));

		}



		int[] result = new int[N];

		Arrays.fill(result, -1);

		for (int i = 0; i < N; ++i) {

			TreeSet<Integer> set = new TreeSet<>();

			for (Map<Integer, Integer> map : list) {

				int order = map.get((i + 1));

				set.add(order);

			}

			if (set.size() == 1) {

				result[i] = set.first();

			}

		}

		for (int i = 0; i < N; ++i) {

			this.writer.print((result[i]) + " ");

		}

		this.writer.println("");

	}



	void showResult() {

		this.writer.flush();

	}



}

