import java.util.Arrays;

import java.util.HashMap;

import java.util.Map;

import java.util.Scanner;



public class Main {



  static int N;

  static int M;

  /** edge -> cost */

  static Map<Edge, Long> edges = new HashMap<>();



  public static void main(String[] args) {

    init();

    solve();

  }



  static void init() {

    Scanner sc = new Scanner(System.in);

    N = sc.nextInt();

    M = sc.nextInt();



    for (int i = 0; i < M; i++) {



      int  K = sc.nextInt();

      long C = sc.nextLong();



      int[] A = new int[K];

      for (int j = 0; j < K; j++) {

        A[j] = sc.nextInt();

      }



      for (int j = 1; j < K; j++) {

        Edge e = new Edge(A[0], A[j]);



        if (edges.containsKey(e)) {

          long cost = edges.get(e);

          edges.put(e, Math.min(cost, C));

        } else {

          edges.put(e, C);

        }

      }

    }

    sc.close();

  }



  static void solve() {



    System.out.println(kruskal());

  }



  /** 最小全域木の総コスト */

  static long kruskal() {



    long ans = 0;

    // 1. 辺をコストの昇順でソート

    // 2. 辺を追加していく （ただし、閉路ができないときだけ追加する）



    WEdge[] wEdges = new WEdge[edges.size()];

    int i = 0;

    for (Edge e : edges.keySet()) {

      wEdges[i] = new WEdge(e.A, e.B, edges.get(e));

      i++;

    }



    Arrays.sort(wEdges);



    UnionFindTree uft = new UnionFindTree(N+1);

    for (WEdge e : wEdges) {

      if (!uft.same(e.A, e.B)) {

        uft.union(e.A, e.B);

        ans += e.cost;

      }

    }



    if (uft.count() > 2) {

      return -1;

    } else {

      return ans;

    }

  }

}



/** 無向辺 */

class Edge {

  int A;

  int B;



  Edge(int A, int B) {

    this.A = A;

    this.B = B;

  }



  @Override

  public boolean equals(Object o) {

    if (this == o) return true;

    if (o == null || getClass() != o.getClass()) return false;

    Edge edge = (Edge) o;

    return (A == edge.A && B == edge.B) || (A == edge.B && B == edge.A);

  }



  @Override

  public int hashCode() {

    return A + B;

  }

}



/** 重み付き辺 */

class WEdge implements Comparable<WEdge>{

  int A;

  int B;

  long cost;



  WEdge(int A, int B, long C) {

    this.A = A;

    this.B = B;

    this.cost = C;

  }



  @Override

  public int compareTo(WEdge o) {

    return Long.compare(this.cost, o.cost);

  }

}



