import java.io.*;

import java.util.*;



public class Main{



   public static void main(String[] args)throws IOException{

      BufferedReader f = new BufferedReader(new InputStreamReader(System.in));

      PrintWriter out = new PrintWriter(System.out);



      int n = Integer.parseInt(f.readLine());



      int[] l = new int[n];

      int[] r = new int[n];



      for(int k = 0; k < n; k++){

         StringTokenizer st = new StringTokenizer(f.readLine());



         l[k] = Integer.parseInt(st.nextToken());

         r[k] = Integer.parseInt(st.nextToken());



      }



      int[] answer = new int[n];

      Arrays.fill(answer,-1);



      int start = 0;

      int maxl = l[0];

      int minr = r[0];

      for(int k = 1; k < n; k++){

         if(start != -1){

            //active streak

            if(l[k] > minr){

               //set everything to minr

               for(int j = start; j < k; j++){

                  answer[j] = minr;

               }

               //no active streak

               start = -1;

               answer[k] = l[k];

            } else if(r[k] < maxl){

               //don't set yet (set answer[k] to whatever is optimal, then fill in after)

               //start new streak

               start = k;

               maxl = l[k];

               minr = r[k];

            } else {

               maxl = Math.max(maxl,l[k]);

               minr = Math.min(minr,r[k]);

            }

         } else {

            //no active streak

            if(l[k] >= answer[k-1]){

               answer[k] = l[k];

            } else {

               //start new streak

               start = k;

               maxl = l[k];

               minr = Math.min(r[k],answer[k-1]);        //cheeky

            }

         }

      }



      //active streak at the end

      if(start != -1){

         for(int k = start; k < n; k++){

            if(start == 0) answer[k] = maxl;

            else answer[k] = minr;

         }

      }



      //fill in missing

      for(int k = n-2; k >= 0; k--){

         if(answer[k] != -1) continue;

         answer[k] = Math.max(answer[k+1],l[k]);

      }



      StringJoiner sj = new StringJoiner(" ");

      for(int k = 0; k < n; k++){

         sj.add("" + answer[k]);

      }

      out.println(sj.toString());







      out.close();

   }





}

