class LazySegmentTree:

    def __init__(self, n, l, e_comp, comp, e_prop, mapping, add_lazy):

        self.e_comp = e_comp

        self.comp = comp

        self.e_prop = e_prop

        self.mapping = mapping

        self.add_lazy = add_lazy

        self.length = 1 << (n - 1).bit_length()

        self.tree = (

            [self.e_comp] * self.length + l + [self.e_comp] * (self.length - len(l))

        )

        self.prop = [e_prop] * (2 * self.length)

        for i in range(self.length - 1, 0, -1):

            self.tree[i] = self.comp(self.tree[2 * i], self.tree[2 * i + 1])



    # 0-indexed で [l, r) を更新する

    def upd(self, l, r, p):

        self.propagate(l, r)

        l += self.length

        r += self.length

        L = l

        R = r

        while r > l:

            if l & 1:

                self.prop[l] = self.add_lazy(self.prop[l], p)

                l += 1

            if r & 1:

                r -= 1

                self.prop[r] = self.add_lazy(self.prop[r], p)

            l >>= 1

