		try (Scanner sc = new Scanner(System.in)) {

			int h = sc.nextInt();

			int w = sc.nextInt();

			int m = sc.nextInt();

			boolean[] isOperatedRow = new boolean[h];

			boolean[] isOperatedColumn = new boolean[w];

			int countOperatedRow = 0;

			int countOperatedColumn = 0;

			long totalOperatedCell = 0;

			SortedMap<Integer, Long> colorToPaintedCell = new TreeMap<>(); // 色0は最後にも処理が必要

			// 逆順で見ていくためにクエリ記憶

			List<Query> queries = new ArrayList<>();

			for (int i = 0; i < m; i++) {

				queries.add(new Query(sc.nextInt(), sc.nextInt() - 1, sc.nextInt()));

			}

			Collections.reverse(queries);

			for (Query query : queries) {

				if (query.t == 1) {

					if (isOperatedRow[query.a]) {

						continue;

					}

					isOperatedRow[query.a] = true;

					countOperatedRow++;

					long operatingCellNum = w - countOperatedColumn;

					if (operatingCellNum <= 0) {

						continue;

					}

					colorToPaintedCell.put(query.x, colorToPaintedCell.getOrDefault(query.x, 0l) + operatingCellNum);

					totalOperatedCell += operatingCellNum;

				} else {

					if (isOperatedColumn[query.a]) {

						continue;

					}

					isOperatedColumn[query.a] = true;

					countOperatedColumn++;

					long operatingCellNum = h - countOperatedRow;

					if (operatingCellNum <= 0) {

						continue;

					}

					colorToPaintedCell.put(query.x, colorToPaintedCell.getOrDefault(query.x, 0l) + operatingCellNum);

					totalOperatedCell += operatingCellNum;

				}

			}

			long notOperatedCell = ((long) h * (long) w) - totalOperatedCell;

			if (notOperatedCell > 0) {

				colorToPaintedCell.put(0, colorToPaintedCell.getOrDefault(0, 0l) + notOperatedCell);

			}

			System.out.println(colorToPaintedCell.size());

			for (Entry<Integer, Long> result : colorToPaintedCell.entrySet()) {

				System.out.println(result.getKey() + " " + result.getValue());

			}

		}



	}



	public static class Query {

		int t;

		int a;

		int x;



		public Query(int t, int a, int x) {

			this.t = t;

			this.a = a;

			this.x = x;

		}

	}

}

