		int n = Integer.parseInt(sc.next());

		long c = Long.parseLong(sc.next());

		long[] a = new long[n];
		long[] sum = new long[n+1];

		for(int i=0; i<n; i++) {
			a[i] = Long.parseLong(sc.next());
			sum[i+1] = sum[i] + a[i];
		}

		long sumMax = 0,  sumMin = 0;
		long max = 0, min = 0;
		int pmax = 1, pmin = 1;
		for(int i=0; i<n; i++) {
			if(sum[i+1]-min>sumMax) {
				sumMax = sum[i+1]-min;
			}
			if(sum[i+1]-max<sumMin) {
				sumMin = sum[i+1]-max;
			}
			if(sum[i+1]>max) {
				max = sum[i+1];
				pmax = i+1;
			}
			if(sum[i+1]<min) {
				min = sum[i+1];
				pmin = i+1;
			}
//			System.out.println(i + " max: " + max + " pmax: " + pmax + " min: " + min + " " + " pmin: " + pmin);
		}

