def can_fill(H, W, tiles):
    board = [[False] * W for _ in range(H)]

    def dfs(x, y, used):
        if y == H:
            return True
        if x == W:
            return dfs(0, y + 1, used)
        if board[y][x]:
            return dfs(x + 1, y, used)
        for i, (a, b) in enumerate(tiles):
            if i in used:
                continue
            for h, w in [(a, b), (b, a)]:
                if (
                    x + w <= W
                    and y + h <= H
                    and all(
                        not board[y + dy][x + dx] for dy in range(h) for dx in range(w)
                    )
                ):
                    for dy in range(h):
                        for dx in range(w):
                            board[y + dy][x + dx] = True
                    if dfs(x + 1, y, used | {i}):
                        return True
                    for dy in range(h):
                        for dx in range(w):
                            board[y + dy][x + dx] = False
        return False

    return dfs(0, 0, set())


