import java.util.*;


public class Main {

	static int N;
	static int H;
	static int W;
	static boolean ans = false;
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		N = sc.nextInt();
		H = sc.nextInt();
		W = sc.nextInt();
		List<T> l = new ArrayList<>();
		for(int i=1;i<=N;i++) {
			int a = sc.nextInt();
			int b = sc.nextInt();
			l.add(new T(a,b));
		}

		boolean[][] G = new boolean[H+1][W+1];
		for(int i=1;i<=H;i++) {
			for(int j=1;j<=W;j++) {
				G[i][j]=false;
			}
		}

		doIt(l, G);
		System.out.println(ans ? "Yes" : "No");
	}

	private static void doIt(List<T> l, boolean[][] G) {
		T start = get(G);
		if(start==null) {
			ans=true;
			return;
		}
		for(T t : l) {
			if(ok(t.a, t.b, start.a, start.b, G)) {
				List<T> nextl = new ArrayList<>(l);
				nextl.remove(t);
				boolean[][] nextg = copy(G);
				use(t.a, t.b, start.a, start.b, nextg);
				doIt(nextl,nextg);
			}
			if(ok(t.b, t.a, start.a, start.b, G)) {
				List<T> nextl = new ArrayList<>(l);
				nextl.remove(t);
				boolean[][] nextg = copy(G);
				use(t.b, t.a, start.a, start.b, nextg);
				doIt(nextl,nextg);
			}
		}
	}
	private static boolean ok(int a, int b, int si, int sj, boolean[][] G) {
		if(si+a-1>H || sj+b-1>W) {
			return false;
		}
		for(int i=si;i<=si+a-1;i++) {
			for(int j=sj;j<=sj+b-1;j++) {
				if(G[i][j]==true) {
					return false;
				}
			}
		}

		return true;
	}

	private static boolean[][] copy(boolean[][] G){
		boolean[][] ret = new boolean[H+1][W+1];
		for(int i=1;i<=H;i++) {
			for(int j=1;j<=W;j++) {
				ret[i][j]=G[i][j];
			}
		}
		return ret;
	}
	private static void use(int a, int b, int si, int sj, boolean[][] G) {
		for(int i=si;i<=si+a-1;i++) {
			for(int j=sj;j<=sj+b-1;j++) {
				G[i][j]=true;
			}
		}
	}

	private static T get(boolean[][] G) {
		for(int i=1;i<=H;i++) {
			for(int j=1;j<=W;j++) {
				if(G[i][j]==false) {
					return new T(i,j);
				}
			}
		}
		return null;
	}

	public static class T{
		int a;
		int b;
		public T(int aa, int bb) {
			a=aa;
			b=bb;
		}

		public boolean equals(Object o) {
			T t = (T)o;
			return a==t.a && b==t.b;
		}
	}
}

