			}
			System.out.println(sb.toString());
		} else {
			System.out.println("No");
		}
	}

	static boolean dfs(int x, int p) {
		b[x] = 0;
		for (Hen h : list.get(x)) {
			int c = h.u;
			if (c == x) {
				c = h.v;
