            # print(p9)
            cnt = 0
            for i in range(m-1):
                cnt += p9[i+1]

            prev_digit = 0
            for i in range(m):
                di = d[i]

                l = 1 if i==0 else 0
                r = di+1 if (i == m-1) else di
                r = int(r)
                for j in range(l, r):
                    if j == prev_digit:
                        continue
                    cnt += p9[m-1-i]
