import java.util.Scanner;
import java.util.ArrayList;
import java.util.TreeMap;

public class Main{
  public static void main(String[] args){
    Scanner sc_i = new Scanner(System.in);
    int n = Integer.parseInt(sc_i.next());
    int q = Integer.parseInt(sc_i.next());
    int[] a = new int[n]; for(int i_i = 0; i_i < n; i_i++){a[i_i] = Integer.parseInt(sc_i.next());};
    var top = new Node(null, a, 0, n);
    var list = new ArrayList<Node>();
    top.coll(list);
    for(int i = 0; i < q; i++){
      int op = Integer.parseInt(sc_i.next());
      int l = Integer.parseInt(sc_i.next());
      int r = Integer.parseInt(sc_i.next());
      if(op == 1){
        list.get(l - 1).set(r);
      }else{
        var tmp = new ArrayList<Node>();
        top.get(0, n, l-1, r, tmp);
        var que = new TreeMap<Integer, Integer>();
        for(var e : tmp){
          if(que.containsKey(e.fq)){que.put(e.fq, que.get(e.fq) + e.fc);}else{que.put(e.fq, e.fc);};
          if(que.containsKey(e.sq)){que.put(e.sq, que.get(e.sq) + e.sc);}else{que.put(e.sq, e.sc);};
        };
        if(que.containsKey(0)){que.remove(0);};
        if(que.size() >= 2){
          que.pollLastEntry();
          System.out.println(que.pollLastEntry().getValue());
        }else{
          System.out.println(0);
        };
      };
    };
  }
  static class Node{
    boolean isEnd;
    Node parent;
    Node left, right;
    int fq, fc;
    int sq, sc;
    public Node(Node parent, int[] base, int s, int e){
      this.parent = parent;
      if(s + 1 == e){
        isEnd = true;
        fq = base[s]; fc = 1;
        sq = 0; sc = 1;
        return;
      };
      isEnd = true;
      int sep = (s + e) / 2;
      left = new Node(this, base, s, sep);
      right = new Node(this, base, sep, e);
      isEnd = false;
      validate();
    }
    public void coll(ArrayList<Node> list){
      if(isEnd){list.add(this); return;};
      left.coll(list); right.coll(list);
    }
    public void set(int value){
      fq = value; validate();
    }
    public void get(int ts, int te, int s, int e, ArrayList<Node> list){
      if(ts == s && te == e){list.add(this); return;};
      int sep = (ts + te) / 2;
      if(s < sep){left.get(ts, sep, s, min(sep, e), list);};
      if(sep < e){right.get(sep, te, max(sep, s), e, list);};
    }
    private void validate(){
      if(isEnd){
        if(parent != null){parent.validate();};
        return;
      };
      if(left.fq > right.fq){
        fq = left.fq; fc = left.fc;
        v2(left.sq, left.sc, right.fq, right.fc);
      }else if(left.fq == right.fq){
        fq = left.fq; fc = left.fc + right.fc;
        v2(left.sq, left.sc, right.sq, right.sc);
      }else{
        fq = right.fq; fc = right.fc;
        v2(left.fq, left.fc, right.sq, right.sc);
      };
      if(parent != null){parent.validate();};
    }
    private void v2(int q1, int c1, int q2, int c2){
      if(q1 > q2){
        sq = q1; sc = c1;
      }else if(q1 == q2){
        sq = q1; sc = c1 + c2;
      }else{
        sq = q2; sc = c2;
      };
    }
  }//node
  public static int min(int... list){
    int ret = list[0]; for(int i = 1; i < list.length; i++){ret = Math.min(ret, list[i]);}; return ret;
  }
  public static int max(int... list){
    int ret = list[0]; for(int i = 1; i < list.length; i++){ret = Math.max(ret, list[i]);}; return ret;
  }
}

