def z_algorithm(s):
    z_len = len(s)
    l = r = 0
    z = [0] * z_len
    z[0] = z_len
    for i in range(1, z_len):
        if z[i-l] < r-i:
            z[i] = z[i-l]
        else:
            if i > r:
                r = i
            while r < z_len and s[r] == s[r-i]:
                r += 1
            z[i] = r - i
            l = i
    return z


def S_in_T(S, T):
    s = len(S)
    return max(z_algorithm(S+'$'+T)[s:]) == s


def minimum(S, T):
    s, t = len(S), len(T)
    z = z_algorithm(T+'$'+S)[s+1:]
    for i in range(t):
        if z[i] == t-i:
            return i-t
    return 0


