    static long[] mn = new long[maxN];
    static long[] mx = new long[maxN];
    static long[] val = new long[maxN];

    static int mult(int a, int b) {
        return (int)((long)a * b % mod);
    }

    static int sum(int a, int b) {
        int s = a + b;
        if (s >= mod) s -= mod;
        return s;
    }

    static int sub(int a, int b) {
        int s = a - b;
        if (s < 0) s += mod;
        return s;
    }

    static int pw(int a, int b) {
        if (b == 0) return 1;
        if ((b & 1) == 1) return mult(a, pw(a, b - 1));
        int res = pw(a, b / 2);
        return mult(res, res);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int tst = sc.nextInt();
        while (tst-- > 0) {
            solve(sc);
        }
        sc.close();
    }

    static void solve(Scanner sc) {
        int n = sc.nextInt();
