                val[x] = Math.max(val[x], Math.abs(S - mx[x]));

                mn[x] = Math.min(mn[x], S);
                mx[x] = Math.max(mx[x], S);
                long c = val[x];
                c = Math.max(c, 2 * mx[x] - S);
                c = Math.max(c, S - 2 * mn[x]);
                cur = Math.min(cur, (c - S) % 2 == 0 ? c : c + 1);
            }
