                printResult(opr);
            } else {
                System.out.println(-1);
            }
        }
    }

     static boolean xx(List<Long> listt, List<int[]> opr) {
        while (true) {
            if (isSorted(listt) && listt.size() == 2) {
                return true;
            }

            if (listt.size() <= 2) {
                return false;
            }

            applyOperation(listt, opr);
        }
    }

     static boolean isSorted(List<Long> listt) {
        for (int i = 1; i < listt.size(); i++) {
            if (listt.get(i - 1) > listt.get(i)) {
                return false;
            }
        }
        return true;
    }

