class Codechef
{
	public static int check(int[] a) {
        int x = 0;
        for (int y : a) {
            x ^= y;
            if (x == 0) return 0;
        }
        return 1;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = scanner.nextInt(); // Read the number of test cases

        while (t-- > 0) {
            int n = scanner.nextInt(); // Read the size of the array
            int[] a = new int[n];

            for (int i = 0; i < n; i++) {
                a[i] = scanner.nextInt(); // Read the elements of the array
            }

            int x = 0;

            for (int i = 0; i < n; i++) {
                boolean found = false;
                for (int j = i; j < n; j++) {
                    if (a[j] != x) {
                        int temp = a[j];
                        a[j] = a[i];
                        a[i] = temp;
                        found = true;
                        break;
                    }
                }
                if (found) {
                    x ^= a[i];
                    continue;
                }
                int temp = a[i - 1];
                a[i - 1] = a[n - 1];
                a[n - 1] = temp;
                break;
            }

            if (check(a) == 1) {
                for (int value : a) {
                    System.out.print(value + " ");
                }
                System.out.println();
            } else {
                System.out.println(-1);
            }
        }

        scanner.close();
	}
}

