import java.util.*;

class DPOnTree {
    static final int N = 100005;
    static int n, d;
    static List<Integer>[] adj = new ArrayList[N];
    static int[] down = new int[N], up = new int[N], ans = new int[N], ache = new int[N];

    public static void dfs(int u, int p) {
        int dd = adj[u].size();
        down[u] = (dd != d) ? 1 : 0;
        for (int v : adj[u]) {
            if (v == p) continue;
            dfs(v, u);
            if (dd == d) ans[u] += down[v];
            else down[u] = Math.max(down[u], 1 + down[v]);
        }
    }

    public static void dfs2(int u, int p) {
        int dd = adj[u].size();
        if (dd != d) {
            int mx = 1 + up[u];
            for (int v : adj[u]) {
                if (v != p) {
                    up[v] = Math.max(up[v], mx);
                    mx = Math.max(mx, 1 + down[v]);
                }
            }
            Collections.reverse(adj[u]);
            mx = 0;
            for (int v : adj[u]) {
                if (v != p) {
                    up[v] = Math.max(up[v], mx);
                    mx = Math.max(mx, 1 + down[v]);
                }
            }
        }

        for (int v : adj[u]) {
            if (v == p) continue;
            int ddv = adj[v].size();
            if (ddv == d) {
                ans[v] += up[v];
                up[v] = 0;
            }
            dfs2(v, u);
        }
    }

    public static void solve(Scanner sc) {
        n = sc.nextInt();
        for (int u = 0; u < n; u++) {
            adj[u] = new ArrayList<>();
            ache[u] = 0;
            ans[u] = 1;
        }

        for (int e = 0; e < n - 1; e++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            adj[u].add(v);
            adj[v].add(u);
        }

        for (int u = 0; u < n; u++) {
            int d = adj[u].size();
            ache[d] = 1;
        }

        for (d = 1; d < n; d++) {
            if (ache[d] == 1) {
                dfs(0, -1);
                Arrays.fill(up, 0);
                dfs2(0, -1);
            }
        }

        for (int u = 0; u < n; u++) {
            System.out.print(ans[u] + " ");
        }
        System.out.println();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int tc = sc.nextInt();
        while (tc-- > 0) {
            solve(sc);
        }
        sc.close();
    }
}

