rt = [1]

# NTT prime
MOD = 998244353
assert MOD & 1

non_quad_res = 2
while pow(non_quad_res, MOD//2, MOD) != MOD - 1:
    non_quad_res += 1
rt = [1]

def ntt(P):
    n = len(P)
    P = list(P)
    assert n and (n - 1) & n == 0

    while 2 * len(rt) < n:
        # 4*len(rt)-th root of unity
        root = pow(non_quad_res, MOD // (4*len(rt)), MOD)
        rt.extend([r * root % MOD for r in rt])

    k = n
    while k > 1:
        for i in range(n//k):
            r = rt[i]
            for j1 in range(i*k, i*k + k//2):
                j2 = j1 + k//2
                z = r * P[j2]
                P[j2] = (P[j1] - z) % MOD
                P[j1] = (P[j1] + z) % MOD
        k //= 2

    rev = [0] * n
    for i in range(1, n):
        rev[i] = rev[i // 2] // 2 + (i & 1) * n // 2
    return [P[r] for r in rev]

def intt(P):
    n = len(P)
    ninv = pow(n, MOD - 2, MOD)
    return ntt([P[-i] * ninv % MOD for i in range(n)])

def ntt_conv(P, Q):
    m = len(P) + len(Q) - 1
    n = 1 << m.bit_length()

    P = P + [0] * (n - len(P))
    Q = Q + [0] * (n - len(Q))
    P, Q = ntt(P), ntt(Q)

    return intt([p * q % MOD for p,q in zip(P, Q)])[:m]



def process(C, Queries):
    n = len(C)
    d = {}
    for x in C:
        if x not in d:
            d[x] = 0 
        d[x]+=1 
    A = [[1, (pow(2, d[x], MOD)-1) % MOD] for x in d]
    start = [[0, len(d)-1, None, None]]
    i = 0
    while i < len(start):
        a, b, c, d = start[i]
        k = len(start)-1
        if a+1 < b:
            start.append([a, (a+b)//2, None, i])
            start.append([(a+b)//2+1, b, None, i])
            i+=1 
        else:
            i+=1
    for i in range(len(start)-1, -1, -1):
        a, b, c, d = start[i]
        if a==b:
            c = A[a]
        elif a+1==b:
            c = ntt_conv(A[a], A[b])
        if d is not None:
            if start[d][2] is None:
                start[d][2] = c 
            elif c is not None:
                start[d][2] = ntt_conv(start[d][2], c)
            start.pop()
        else:
            start = c 
    while len(start) < n+1:
        start.append(0)
    answer = [0]
    for x in start:
        answer.append((answer[-1]+x) % MOD)
    for L, R in Queries:
        sys.stdout.write(f"{(answer[R+1]-answer[L]) % MOD}\n")
    return 

