import java.util.*;
import java.io.*;

  class PairsSumWithLengthX {

    static class SegmentTree {
        long[] segTree;

        public SegmentTree(int m) {
            segTree = new long[4 * m];
        }

        public long query(int ind, int low, int high, int l, int r) {
            if (l <= low && high <= r) {
                return segTree[ind];
            }
            if (low > r || high < l) {
                return 0;
            }
            int mid = (low + high) / 2;
            return query(2 * ind, low, mid, l, r) + query(2 * ind + 1, mid + 1, high, l, r);
        }

        public void update(int ind, int low, int high, int idx, int val) {
            if (low == high) {
                segTree[ind] += val;
                return;
            }
            int mid = (low + high) / 2;
            if (idx <= mid) {
                update(2 * ind, low, mid, idx, val);
            } else {
                update(2 * ind + 1, mid + 1, high, idx, val);
            }
            segTree[ind] = segTree[2 * ind] + segTree[2 * ind + 1];
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int t = Integer.parseInt(br.readLine());

        while (t-- > 0) {
            String[] nx = br.readLine().split(" ");
            long n = Long.parseLong(nx[0]);
            int x = Integer.parseInt(nx[1]);

            String[] aStr = br.readLine().split(" ");
            long[] a = new long[(int) n];
            for (int i = 0; i < n; i++) {
                a[i] = Long.parseLong(aStr[i]);
            }

            if (n == 1) {
                System.out.println(0);
            } else {
                long[] b = Arrays.copyOf(a, (int) n);
                Arrays.sort(b);
                b = Arrays.stream(b).distinct().toArray();

                SegmentTree st = new SegmentTree(b.length);
                long mx = (long) Math.pow(10, x), mn = (long) Math.pow(10, x - 1);
                long ans = 0;

                for (int i = 0; i < n; i++) {
                    int l = lowerBound(b, mn - a[i]);
                    int r = lowerBound(b, mx - a[i]) - 1;
                    ans += (n - i) * st.query(1, 0, b.length - 1, l, r);
                    int ind = lowerBound(b, a[i]);
                    st.update(1, 0, b.length - 1, ind, i + 1);
                }
                System.out.println(ans);
            }
        }
    }

    private static int lowerBound(long[] array, long value) {
        int low = 0, high = array.length;
        while (low < high) {
            int mid = (low + high) / 2;
            if (array[mid] < value) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }
}

