def mul(a, b):
    n = len(a)
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                res[i][j] += a[i][k] * b[k][j]
                res[i][j] %= M
    return res


def power(a, k):
    n = len(a)
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        res[i][i] = 1

    while k:
        if k & 1:
            res = mul(a, res)
        a = mul(a, a)
        k >>= 1
    return res


def solve():
