for i in range(1, N):
    fact[i] = fact[i-1] * i % M

inv_fact[N-1] = pow(fact[N-1], M-2, M)
for i in range(N-2, 0, -1):
    inv_fact[i] = inv_fact[i+1] * (i+1) % M


def comb(n, k):
    if k < 0 or k > n:
        return 0
    return fact[n] * inv_fact[k] % M * inv_fact[n-k] % M


def ways(n, k):
    return comb(n+k-1, k-1)


def solve():
    M = 10 ** 9 + 7
    n, = read()
    if n < 4:
        print(0)
    elif n == 4:
        print(1)
    else:
        # every every node having degree of 2 and n is even
        # at least one node 3+ and there other nodes having degree 2+
        ans = ways(n, n)
        if n & 1:
            ans -= 1
        for i in range(1, 4):
            ans -= comb(n, i) * ways(n-i, i)
        print(ans % M)


