t = int(input())

def sumdiff(arr, p, value):
    n = len(arr)
    beg = 0
    end = n - 1
    while beg <= end:
        mid = (beg + end) // 2
        if arr[mid] <= value:
            beg = mid + 1
        else:
            end = mid - 1
    pos = beg - 1
    return value * (pos + 1) - p[pos + 1] + p[n] - p[pos + 1] - value * (n - pos - 1)

for _ in range(t):
    m, n = map(int, input().split())
    grid = []
    for _ in range(m):
        grid.append(list(map(int, input().split())))
    res = [[0] * n for _ in range(m)]
    groupsx = [[] for _ in range(3)]
    groupsy = [[] for _ in range(3)]
    px = [[0] for _ in range(3)]
    py = [[0] for _ in range(3)]
    for i in range(m):
        for j in range(n):
            cell = grid[i][j]
            if cell > 0:
                if cell == 1 or cell == 3:
                    groupsx[1].append(i + j)
                    groupsy[1].append(i - j)
                if cell == 2 or cell == 3:
                    groupsx[2].append(i + j)
                    groupsy[2].append(i - j)
    for i in range(3):
        groupsx[i].sort()
        for el in groupsx[i]:
            px[i].append(px[i][-1] + el)
        groupsy[i].sort()
        for el in groupsy[i]:
            py[i].append(py[i][-1] + el)
    for i in range(m):
        for j in range(n):
            a = sumdiff(groupsx[1], px[1], i + j) + sumdiff(groupsy[1], py[1], i - j)
            b = sumdiff(groupsx[2], px[2], i + j) + sumdiff(groupsy[2], py[2], i - j)
            res[i][j] = abs(a - b) // 2
    print("\n".join(" ".join(map(str, r)) for r in res))

