    fact[i] = fact[i-1] * i % M

inv_fact[N-1] = pow(fact[N-1], M-2, M)
for i in range(N-2, 0, -1):
    inv_fact[i] = inv_fact[i+1] * (i+1) % M


def comb(n, k):
    if k < 0 or k > n:
        return 0
    return fact[n] * inv_fact[k] % M * inv_fact[n-k] % M


