import java.util.*;

public class Main {
    private static final int MOD = 998244353;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int t = sc.nextInt(); // Number of test cases
        while (t-- > 0) {
            int n = sc.nextInt();
            int[] p = new int[2 * n];
            for (int i = 0; i < 2 * n; i++) {
                p[i] = sc.nextInt();
            }

            // pair > n with <= n
            // suppose x pairs >n and y pairs <= n already; x >= y
            // have to make x-y pairs where both are >= n
            // choose the smallest x-y unpaired elements to be subtracted
            // then distribute the rest

            int[] mark = new int[2 * n + 1];
            int small = 0, large = 0, empty = 0;
            for (int i = 0; i < 2 * n; i += 2) {
                if (p[i] == 0 && p[i + 1] == 0) empty++;
                if (p[i] != 0) {
                    mark[p[i]]++;
                    mark[p[i + 1]]++;
                }
                if (p[i + 1] != 0) {
                    mark[p[i]]++;
                    mark[p[i + 1]]++;
                }
            }

            long ans = 1;
            for (int i = 1; i <= empty; i++) {
                ans = (2 * ans) % MOD;
            }

            int x = 0, y = 0;
            small = (int) Arrays.stream(mark, 1, n + 1).filter(val -> val == 2).count();
            large = (int) Arrays.stream(mark, n + 1, 2 * n + 1).filter(val -> val == 2).count();
            if (small <= large) {
                int want = large / 2 - small / 2;

                for (int i = n + 1; i <= 2 * n; i++) {
                    if (mark[i] == 0) x++;
                }
                for (int i = n; i >= 1; i--) {
                    if (mark[i] == 2) continue;
                    if (want > 0) {
                        if (mark[i] == 0) x++;
                        want--;
                    } else {
                        if (mark[i] == 0) y++;
                    }
                }
            } else {
                int want = small / 2 - large / 2;

                for (int i = 1; i <= n; i++) {
                    if (mark[i] == 0) x++;
                }
                for (int i = n + 1; i <= 2 * n; i++) {
                    if (mark[i] == 2) continue;
                    if (want > 0) {
                        if (mark[i] == 0) x++;
                        want--;
                    } else {
                        if (mark[i] == 0) y++;
                    }
                }
            }

            for (int i = 1; i <= x; i++) {
                ans = (ans * i) % MOD;
            }
            for (int i = 1; i <= y; i++) {
                ans = (ans * i) % MOD;
            }
            System.out.println(ans);
        }
        sc.close();
    }
}

