import java.util.*;

public class Main {

    // Segment Tree class
    static class SegmentTree {
        long[] seg;
        int size;
        long identity;
        SegmentCombiner combiner;

        interface SegmentCombiner {
            long combine(long obj1, long obj2);
        }

        public SegmentTree(int n, SegmentCombiner combiner, long defaultValue) {
            this.size = n;
            this.identity = defaultValue;
            this.combiner = combiner;
            this.seg = new long[2 * n];
            Arrays.fill(this.seg, defaultValue);
        }

        void update(int pos, long val) {
            for (seg[pos += size] = val; pos > 1; pos /= 2) {
                seg[pos / 2] = combiner.combine(seg[pos], seg[pos ^ 1]);
            }
        }

        long query(int l, int r) { // query [l, r]
            r++;
            long leftRes = identity, rightRes = identity;
            for (l += size, r += size; l < r; l /= 2, r /= 2) {
                if ((l & 1) == 1) leftRes = combiner.combine(leftRes, seg[l++]);
                if ((r & 1) == 1) rightRes = combiner.combine(seg[--r], rightRes);
            }
            return combiner.combine(leftRes, rightRes);
        }
    }

    // Combiner function for Segment Tree to find max
    static long max_value(long a, long b) {
        return Math.max(a, b);
    }

    // Function to solve each test case
    static void solve_test_case(Scanner scanner) {
        int n = scanner.nextInt();
        long[] arr = new long[n];
        SegmentTree st = new SegmentTree(n, Main::max_value, 0);

        for (int i = 0; i < n; ++i) {
            arr[i] = scanner.nextLong();
            st.update(i, arr[i]);
        }

        long[] previousGreaterEqual = new long[n];
        long[] nextGreaterEqual = new long[n];
        Arrays.fill(previousGreaterEqual, -1);
        Arrays.fill(nextGreaterEqual, n);
        Stack<Long> stack = new Stack<>();

        for (int i = 0; i < n; ++i) {
            while (!stack.isEmpty() && arr[stack.peek().intValue()] <= arr[i]) {
                stack.pop();
            }
            if (stack.size() == 1) {
                previousGreaterEqual[i] = stack.peek();
            } else if (stack.size() > 1) {
                System.out.println(0);
                return;
            }
            stack.push((long) i);
        }

        long minK = 0;
        long extra = n;
        long lastSpecial = n;
        long[] cannotChange = new long[n];
        boolean hadChange = false;
        long maxDifference = 0;

        for (int i = n - 1; i >= 0; --i) {
            if (previousGreaterEqual[i] != -1) {
                minK = Math.max(minK, arr[(int) previousGreaterEqual[i]] - arr[i]);
                st.update(i, arr[(int) previousGreaterEqual[i]]);
                cannotChange[(int) previousGreaterEqual[i]] = 1;
                if (hadChange) {
                    extra = Math.min(extra, maxDifference);
                }
            }
            if (cannotChange[i] == 1) {
                hadChange = true;
                maxDifference = 0;
            }
            if (hadChange && i > 0) {
                maxDifference = Math.max(maxDifference, arr[i] - arr[i - 1]);
            }
        }

        long maxK = extra;
        long answer = (maxK * (maxK + 1)) / 2;
        answer -= (minK * (minK - 1)) / 2;
        System.out.println(Math.max(answer, 0));
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int totalTests = scanner.nextInt();

        for (int testNo = 1; testNo <= totalTests; ++testNo) {
            solve_test_case(scanner);
        }

        scanner.close();
    }
}

