import java.util.Scanner;

class Main {

    static final int MOD = 998244353;

    // Fast exponentiation: computes x^y % MOD
    static long powerMod(long x, long y) {
        long res = 1;
        x %= MOD;
        while (y > 0) {
            if ((y & 1) == 1) {
                res = res * x % MOD;
            }
            x = x * x % MOD;
            y >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int T = sc.nextInt();

        while (T-- > 0) {
            long N = sc.nextLong();
            long M = sc.nextLong();
            long K = N / 2;
            long M_mod = N % 2;
            long pow_m_mod = (M_mod == 1) ? powerMod(M, 1) : 1;

            // Precompute powers of M
            // Now, compute sum_f
            long sum_f = 0;
            for (long d = 1; d <= M; d++) {
                long a = M / d;
                long b = M % d;
                long term1 = (b * ((a + 1) * (a + 1) % MOD)) % MOD;
                long term2 = ((d - b) * (a * a % MOD)) % MOD;
                long sum_c_r_sq = (term1 + term2) % MOD;
                long pow_sum = (K == 0) ? 1 : powerMod(sum_c_r_sq, K);
                long contrib = pow_sum * pow_m_mod % MOD;
                sum_f = (sum_f + contrib) % MOD;
            }

            // Compute term to subtract
            long pow_M_K = (K == 0) ? 1 : powerMod(M, K);
            long term = pow_M_K;
            if (M_mod == 1) {
                term = term * powerMod(M, 1) % MOD;
            } else {
                term = term * 1 % MOD;
            }
            long add_val = (1 + M) % MOD;
            term = term * add_val % MOD;

            // Subtract term
            sum_f = (sum_f - term) % MOD;
            if (sum_f < 0) {
                sum_f += MOD;
            }

            System.out.println(sum_f);
        }
        sc.close();
    }
}

