import java.util.*;

public class Main {

    static Scanner s = new Scanner(System.in);

    static int MOD = 1000000007;

    public static long modInverse(long a, long m) {
        long m0 = m;
        long y = 0, x = 1;

        if (m == 1)
            return 0;

        while (a > 1) {
            long q = a / m;
            long t = m;

            m = a % m;
            a = t;
            t = y;

            y = x - q * y;
            x = t;
        }

        // Make x positive
        if (x < 0)
            x += m0;

        return x;
    }

    public static long find(int n, int r) {
        if (r > n)
            return 0;

        if (r > n - r)
            r = n - r;

        long num = 1, den = 1;

        for (int i = 0; i < r; i++) {
            num = (num * (n - i)) % MOD;
            den = (den * (i + 1)) % MOD;
        }

        // Calculate (num * den^(-1)) % MOD using modular inverse
        long result = (num * modInverse(den, MOD)) % MOD;

        return result;
    }

    public static void solve() {
        int n = s.nextInt();
        int m = s.nextInt();

        List<String> arr = new ArrayList<>();
        for (int i=0;i<n;i++) arr.add(s.next());
        List<HashSet<Integer>> ls = new ArrayList<>();
        for (int i=0;i<n;i++) ls.add(new HashSet<>());
        for (int i=0;i<n;i++){
            for (int j=0;j<m;j++){
                if (arr.get(i).charAt(j)=='1') ls.get(i).add(j);
            }
            if (ls.get(i).size()<2) ls.get(i).clear();
        }
        // System.out.println(ls);

        for (int i=n-2;i>0;i--){
            for (Integer num : ls.get(i)){
                if (ls.get(i+1).contains(num)){
                    ls.get(i).addAll(ls.get(i+1));
                    break;
                }
            }
        }

        // System.out.println(ls);

        if (n==1||ls.get(1).size()<2){
            System.out.println(1);
            return;
        }
        int noofone = 0;
       for (Integer num : ls.get(1)){
           if (arr.get(0).charAt(num)=='1') noofone++;
       }

//        System.out.println(noofone);
//        System.out.println(ls.get(1).size());

        long ans = find(ls.get(1).size(),noofone);

        System.out.println(ans);



    }





    public static void main(String[] args) {
        int t =1;

        t = s.nextInt();
        s.nextLine();

        while (t-- >0){
            solve();
        }
    }
}

