def solve():
    n = int(input())
    p = list(map(int, input().split()))

    gre = [-1] * n  # Stores the index of the equal or greater element to the left of ith index
    s = []
    for i in range(n-1, -1, -1):
        while s and p[i] >= p[s[-1]]:
            gre[s.pop()] = i
        s.append(i)

    dis = 0
    prev = [-1] * n  # Stores the previous occurrence of element i
    maxm = [0] * n   # Gives the sum of maximums of all subarrays from 0 to ith index
    ans = 0
    for i in range(n):
        if gre[i] == -1:
            maxm[i] = (i + 1) * (p[i] + 1)
        else:
            maxm[i] = (i - gre[i]) * (p[i] + 1) + maxm[gre[i]]
        dis += i - prev[p[i]]
        ans += maxm[i] - dis
        prev[p[i]] = i

    print(ans)

def main():
    t = int(input())
    for _ in range(t):
        solve()

