    static final int MOD_VALUE = 998244353; // Constant modulus value for operations

    // Fast exponentiation method to compute (base^exp) % mod
    public static long modExponentiation(long base, long exp, long mod) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) { // If exponent is odd, multiply the result by base
                result = (result * base) % mod;
            }
            base = (base * base) % mod; // Square the base
            exp >>= 1; // Divide the exponent by 2
        }
        return result;
    }

