        while (testCases-- > 0) {
            int arraySize = Integer.parseInt(reader.readLine()); // Read size of array (n)
            int fullArraySize = 2 * arraySize; // Full size of the array, which is 2 * n
            String[] inputArray = reader.readLine().split(" "); // Read the array input

            // Array to store input
            int[] inputValues = new int[fullArraySize];
            for (int i = 0; i < fullArraySize; i++) {
                inputValues[i] = Integer.parseInt(inputArray[i]); // Parse each input as integer
            }

            // Initialize counts for numbers in different ranges
            int smallValuesCount = arraySize;
            int largeValuesCount = arraySize;

            // Loop through input array
            for (int i = 0; i < fullArraySize; i++) {
                if (inputValues[i] <= arraySize && inputValues[i] > 0) {
                    smallValuesCount--; // Count values less than or equal to n
                } else if (inputValues[i] > arraySize) {
                    largeValuesCount--; // Count values greater than n
                }
            }

            int result = 1; // Final result initialization
            int zeroPairs = 0; // Count of zero pairs

            // Count pairs of zeros in the array
            for (int i = 0; i + 1 < fullArraySize; i += 2) {
                if (inputValues[i] == inputValues[i + 1] && inputValues[i] == 0) {
                    zeroPairs++; // Count zero pairs
                }
            }

