from collections import deque

t = int(input())
while t > 0:
    t -= 1
    n = int(input())

    adj = [[] for _ in range(n + 1)]
    deg = [0] * (n + 1)

    for _ in range(n - 1):
        u, v = map(int, input().split())
        adj[u].append(v)
        adj[v].append(u)
        deg[u] += 1
        deg[v] += 1

    inv = False
    if n <= 3:
        inv = True
    else:
        for i in range(1, n + 1):
            if deg[i] == n - 1:
                inv = True
                break

    if inv:
        print("-1")
        continue

    d = [-1] * (n + 1)
    q = deque([1])
    d[1] = 0
    u = 1

    while q:
        cur = q.popleft()
        for nei in adj[cur]:
            if d[nei] == -1:
                d[nei] = d[cur] + 1
                q.append(nei)
                if d[nei] > d[u]:
                    u = nei

    d = [-1] * (n + 1)
    q = deque([u])
    d[u] = 0
    v = u

    while q:
        cur = q.popleft()
        for nei in adj[cur]:
            if d[nei] == -1:
                d[nei] = d[cur] + 1
                q.append(nei)
                if d[nei] > d[v]:
                    v = nei

    p = [-1] * (n + 1)
    q = deque([u])
    p[u] = 0

    while q:
        cur = q.popleft()
        if cur == v:
            break
        for nei in adj[cur]:
            if p[nei] == -1:
                p[nei] = cur
                q.append(nei)

    path = []
    node = v
    while node != 0:
        path.append(node)
        node = p[node]

    path.reverse()

    if len(path) % 2 == 0:
        c = path[len(path) // 2 - 1]
    else:
        c = path[len(path) // 2]

    dep = [-1] * (n + 1)
    vis = [False] * (n + 1)
    l_d = [[] for _ in range(n + 1)]
    nl_d = [[] for _ in range(n + 1)]

    q = deque([c])
    vis[c] = True
    dep[c] = 0

    while q:
        node = q.popleft()
        cur_dep = dep[node]

        if deg[node] == 1 and node != c:
            l_d[cur_dep].append(node)
        else:
            nl_d[cur_dep].append(node)

        for nei in adj[node]:
            if not vis[nei]:
                vis[nei] = True
                dep[nei] = cur_dep + 1
                q.append(nei)

    ord_nodes = []
    for d_level in range(len(l_d)):
        for node in l_d[d_level]:
            ord_nodes.append(node)
        for node in nl_d[d_level]:
            ord_nodes.append(node)

    print(" ".join(map(str, ord_nodes)))

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        int tt = sc.nextInt();
        while (tt-- > 0) {
            int n = sc.nextInt();
            N = n;
            ed = new List[n + 1];
            for (int i = 0; i <= n; i++) {
                ed[i] = new ArrayList<>();
            }
            for (int i = 1; i < n; i++) {
                int u = sc.nextInt(), v = sc.nextInt();
                ed[u].add(v);
                ed[v].add(u);
            }
            int[] t = bfs(1);//此时 t[0] = 直径的一个端点
            t = bfs(t[0]);//此时 t[0] = 直径的另一个端点，t[1] = 直径的值
            if (t[1] <= 2) {
                out.println(-1);
                continue;
            }
            size = new int[n + 1];
            weight = new int[n + 1];
            centroid = new int[2];
            dfs(1, 0);
            int cc = centroid[0];
            dep = new int[n + 1];
            dfs3(cc, 0);


            dfs2(cc, 0);
            out.println();
        }
        out.close();
    }

    static List<Integer>[] ed;
    static int[] size;//保存以当前节点为根的子树大小
    static int[] weight;//保存节点的所有儿子节点中的最大节点数
    static int[] centroid;//保存重心编号，重心最多两个
    static int N;

    //树的直径
    static int[] bfs(int s) {
        int max = -1, idx = -1;
        boolean[] vis = new boolean[N + 1];
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{s, 0});
        while (!q.isEmpty()) {
            int[] t = q.poll();
            int u = t[0], w = t[1];
            if (vis[u]) continue;
            vis[u] = true;
            if (w > max) {
                max = w;
                idx = u;
            }
            for (int v : ed[u]) {
                q.offer(new int[]{v, w + 1});
            }
        }
        return new int[]{idx, max};//返回距离 s 最远的点以及具体的距离
    }

    static void dfs(int u, int p) {
        size[u] = 1;
        for (int v : ed[u]) {
            if (v == p) continue;
            dfs(v, u);
            weight[u] = Math.max(weight[u], size[v]);
            size[u] += size[v];
        }
        weight[u] = Math.max(weight[u], N - size[u]);
        if (weight[u] <= N / 2) {//根据重心的定义，以树的重心为根时，所有子树的大小都不超过整棵树大小的一半。
            if (centroid[0] == 0) centroid[0] = u;
            else centroid[1] = u;
        }
    }

    static int[] dep;

    static void dfs3(int u, int p) {
        dep[u] = dep[p] + 1;
        for (int v : ed[u]) {
            if (v == p) continue;
            dfs3(v, u);

        }
        for (int v : ed[u]) {
            if (v == p) continue;
            dep[u] = Math.max(dep[u], dep[v]);

        }

    }


    static void dfs2(int u, int p) {
        out.print(u + " ");
        List<Integer> l = new ArrayList<>();

        for (int v : ed[u]) {
            if (v == p) continue;
            l.add(v);
        }
        l.sort((o1, o2) -> dep[o1] - dep[o2]);
        for (int v : l) dfs2(v, u);

    }


    static Kattio sc = new Kattio();
    static PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

    static class Kattio {
        static BufferedReader r;
        static StringTokenizer st;

        public Kattio() {
            r = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            try {
                while (st == null || !st.hasMoreTokens()) {
                    st = new StringTokenizer(r.readLine());
                }
                return st.nextToken();
            } catch (Exception e) {
                return null;
            }
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

