    static TreeMap<Integer, Integer> val = new TreeMap<>();

    static void updateAns(int l, int r) {
        while (true) {
            Map.Entry<Integer, Integer> entry = val.lowerEntry(r + 1);
            if (val.isEmpty() || entry == null) {
                val.put(l, r);
                ans += r - l + 1;
                break;
            }
            int x = entry.getKey();
            int y = entry.getValue();
            if (l > y) {
                val.put(l, r);
                ans += r - l + 1;
                break;
            } else {
                ans -= y - x + 1;
                val.remove(x);
                l = Math.min(l, x);
                r = Math.max(r, y);
            }
        }
    }

    static void calc(int u, int v) {
        int l, r;
        l = v - u + 1;
        r = u;
        if (l <= r) updateAns(l, r);
        l = Math.max(v - u + 1, u);
        r = v;
        if (l <= r) updateAns(l, r);
        l = v;
        r = u + v - 1;
        if (l <= r) updateAns(l, r);
    }

    static void update(int u) {
        Integer lower = cur.lower(u);
        Integer higher = cur.higher(u);

        if (lower != null) {
