    curr_size = seq[0][2]
    for i in range(1, len(seq)):
        if seq[i][0] > seq[i-1][1]:
            curr -= f(curr_size) + f(seq[i][2])
            curr_size += seq[i][2]
            curr += f(curr_size)
        else:
            curr_size = seq[i][2]
