public class Main {

    public static void solve(Scanner sc) {

        int n = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }

        int[] vec = new int[n - 1];
        TreeSet<Integer> st = new TreeSet<>();  // Using TreeSet to maintain order
        int c = 1;


        for (int i = 0; i < n - 1; i++) {
            st.add(a[i]);
            if (st.last()==(i + 1)) {  
                vec[i] = -1;
                c++;
                continue;
            }
            st.remove(a[i]);
            st.add(a[i + 1]);
            if (st.last() == (i + 1)) { 
                vec[i] = 1;
            }
            st.remove(a[i + 1]);
            st.add(a[i]);
        }

        int mx = 0, sum = 0;

        // Max subarray sum logic, even indices
        for (int i = 0; i < n - 1; i += 2) {
            sum += vec[i];
            mx = Math.max(mx, sum);
            if (sum < 0) sum = 0;
        }

        sum = 0;
        // Max subarray sum logic, odd indices
        for (int i = 1; i < n - 1; i += 2) {
            sum += vec[i];
            mx = Math.max(mx, sum);
            if (sum < 0) sum = 0;
        }

        System.out.println(c + mx);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int t = sc.nextInt();
        while (t-- > 0) {
            solve(sc);
        }
    }
}

