import java.util.Scanner;

class Codechef {
    static final int MODULO = 1000000007;
    static long[] fact;
    static long[] invFact;
    static int MAX_LIMIT = 2000000;

    public static void main(String[] args) {
        prepareFactorials();
        Scanner input = new Scanner(System.in);
        int testCount = input.nextInt();

        while (testCount-- > 0) {
            int x = input.nextInt();
            int y = input.nextInt();
            int sum = x + y;

            int[] pattern = new int[sum + 1];
            for (int i = 1; i <= sum; i++) {
                pattern[i] = (i / 2) % 2;
            }

            long[] zeroCount = new long[sum + 2];
            long[] oneCount = new long[sum + 2];
            zeroCount[sum + 1] = 0;
            oneCount[sum + 1] = 0;

            for (int i = sum; i >= 1; i--) {
                zeroCount[i] = zeroCount[i + 1] + (pattern[i] == 0 ? 1 : 0);
                oneCount[i] = oneCount[i + 1] + (pattern[i] == 1 ? 1 : 0);
            }

            long positiveDiffs = 0, negativeDiffs = 0, zeroDiffs = 0;
            for (int i = 1; i <= sum; i++) {
                long difference;
                if (i % 2 == 0) {
                    difference = oneCount[i] - zeroCount[i];
                } else {
                    difference = zeroCount[i] - oneCount[i];
                }
                if (difference == 1) {
                    positiveDiffs++;
                } else if (difference == -1) {
                    negativeDiffs++;
                } else {
                    zeroDiffs++;
                }
            }

            long finalResult = 0;
            int maxPairings = Math.min(Math.min((int)positiveDiffs, (int)negativeDiffs), y / 2);

            for (int c = 0; c <= maxPairings; c++) {
                int remainingY = y - 2 * c;
                if (remainingY < 0 || remainingY > zeroDiffs) {
                    continue;
                }
                long combination = calculateCombo((int)positiveDiffs, c);
                combination = combination * calculateCombo((int)negativeDiffs, c) % MODULO;
                combination = combination * calculateCombo((int)zeroDiffs, remainingY) % MODULO;
                finalResult = (finalResult + combination) % MODULO;
            }

            System.out.println(finalResult);
        }
        input.close();
    }

    static void prepareFactorials() {
        fact = new long[MAX_LIMIT + 1];
        invFact = new long[MAX_LIMIT + 1];
        fact[0] = 1;
        for (int i = 1; i <= MAX_LIMIT; i++) {
            fact[i] = fact[i - 1] * i % MODULO;
        }
        invFact[MAX_LIMIT] = modPow(fact[MAX_LIMIT], MODULO - 2);
        for (int i = MAX_LIMIT - 1; i >= 0; i--) {
            invFact[i] = invFact[i + 1] * (i + 1) % MODULO;
        }
    }

    static long calculateCombo(int n, int k) {
        if (n < k || k < 0) {
            return 0;
        }
        return fact[n] * invFact[k] % MODULO * invFact[n - k] % MODULO;
    }

    static long modPow(long base, long exp) {
        long result = 1;
