def is_similar(a, b):
    na, nb = len(a), len(b)
    if na == nb:
        return sum(1 for x, y in zip(a, b) if x != y) <= 1
    elif abs(na - nb) == 1:
        s, t = (a, b) if na > nb else (b, a)
        ns, nt = len(s), len(t)
        i, j = 0, 0
        while i < ns and j < nt:
            if s[i] != t[j]:
                return s[i+1:] == t[j:] or s[i:] == t[j+1:]
            i += 1
            j += 1
        return True
    return False

