public class Main {

    private static String conversion(int n) {
        StringBuilder sb = new StringBuilder();
        while (n > 0) {
            sb.append(n % 2);
            n /= 2;
        }
        return sb.reverse().toString();
    }


    private static boolean isLucky(String str) {
        if (str == null || str.length() == 0) {
            return false;
        }

        int n = str.length();
        for (int i = 0; i < n; ) {
            int j = i;

            while (j < n && str.charAt(j) == str.charAt(i)) {
                j++;
            }

            if (j - i < 2) {
                return false;
            }

            i = j;
        }
        return true;
    }

    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int a = scan.nextInt();
        int b = scan.nextInt();
        int ans = 0;
        for (int i = a; i <= b; i++) {
            String s = conversion(i);
            if (isLucky(s)) {
                ans++;
            }
        }
        System.out.println(ans);
    }
}

