public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        boolean isBeautifulDance = true;
        int n = scan.nextInt();
        int diff = scan.nextInt();
        int[] students = new int[2 * n];
        for (int i = 0; i < 2 * n; i++) {
            students[i] = scan.nextInt();
        }
        Arrays.sort(students);
        for (int i = 0; i < 2 * n; i += 2) {
            int heightDiff = Math.abs(students[i] - students[ i + 1]);
            if (heightDiff > diff) {
                isBeautifulDance = false;
                break;
            }
        }
        if (isBeautifulDance) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }
        scan.close();
    }
}

