                if tubes[idx_to_empty][-1] == tubes[2][0]:
                    move(idx_to_empty, 2)
                else:
                    move(idx_to_empty, idx_to_empty ^ 1)
            move(2, idx_to_empty)  
            break
    assert len(moves) == ans
    for a, b in moves:
        print(1 + a, 1 + b)

T = int(input())
for _ in range(T):
    solve()

