import java.io.*;
import java.util.*;

class Main {
    static final int N = 500001;
    static int tot;
    static int[] bound = new int[N];
    static class BIT {
        int[] array = new int[N];

        void add(int x, int y) {
            while (x <= tot) {
                array[x] += y;
                x += x & -x;
            }
        }

        int query(int x) {
            int result = 0;
            while (x > 0) {
                result += array[x];
                x -= x & -x;
            }
            return result;
        }
    }

    static class Node implements Comparable<Node> {
        int l, r, k, id;

        @Override
        public int compareTo(Node b) {
            return r - l > b.r - b.l ? -1 : 1;
        }
    }
    static int upperBound(int[] arr, int len, int target) {
        int l = 1, r = len + 1;
        while (l < r) {
            int mid = (l + r) / 2;
            if (arr[mid] <= target)
                l = mid + 1;
            else
                r = mid;
        }
        return l;
    }
    static int lowerBound(int[] arr, int len, int target) {
        int l = 1, r = len + 1;
        while (l < r) {
            int mid = (l + r) / 2;
            if (arr[mid] < target)
                l = mid + 1;
            else
                r = mid;
        }
        return l;
    }


    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        Node[] cultivars = new Node[N];
        Node[] culs = new Node[N];
        BIT tree1 = new BIT();
        BIT tree2 = new BIT();
        for (int i = 1; i <= n; ++i) {
            st = new StringTokenizer(br.readLine());
            cultivars[i] = new Node();
            cultivars[i].l = Integer.parseInt(st.nextToken());
            cultivars[i].r = Integer.parseInt(st.nextToken());
            cultivars[i].k = Integer.parseInt(st.nextToken());
            cultivars[i].id = i;
            bound[++tot] = cultivars[i].l;
            bound[++tot] = cultivars[i].r;
            culs[i] = new Node();
            culs[i].l = cultivars[i].l;
            culs[i].r = cultivars[i].r;
            culs[i].k = cultivars[i].k;
            culs[i].id = i;
        }

        Arrays.sort(cultivars, 1, n + 1);
        Arrays.sort(bound, 1, tot + 1);
        Arrays.sort(culs, 1, n + 1, new Comparator<Node>() {
            @Override
            public int compare(Node x, Node y) {
                return y.k - x.k;
            }
        });

        int pre = 1;
        int[] ans = new int[n + 1];
        for (int i = 1; i <= n; ++i) {
            while (pre <= n && culs[pre].k > cultivars[i].r - cultivars[i].l) {
                updateAns(tree1, tree2, ans, culs[pre]);
                pre++;
            }

            cultivars[i].l = lowerBound(bound, tot, cultivars[i].l);
            cultivars[i].r = lowerBound(bound, tot, cultivars[i].r);

            tree1.add(cultivars[i].r, 1);
            tree2.add(cultivars[i].l, 1);

        }
        while (pre <= n) {
            updateAns(tree1, tree2, ans, culs[pre]);
            pre++;
        }
        for (int i = 1; i <= n; ++i)
            System.out.println(ans[i] - 1);
    }

    private static void updateAns(BIT tree1, BIT tree2, int[] ans, Node culs) {
        int x = lowerBound(bound, tot, culs.l + culs.k);
        int y = upperBound(bound, tot, culs.r - culs.k);
        ans[culs.id] += tree2.query(y - 1) - tree1.query(x - 1);
    }
}

