public class Main {
    public static void main(String[] args) {
        Scanner kb = new Scanner(System.in);
        for (int t = kb.nextInt(); t > 0; t --) {
            int n = kb.nextInt();
            int m = kb.nextInt();
            int k = kb.nextInt();
            int[][] delta = new int[m][2];

            for (int i = 0; i < m; i ++)
                Arrays.fill(delta[i], 1001);
            for (int i = 0; i < m; i ++) {
                for (int j = 0; j < k; j ++) {
                    int x = kb.nextInt();
                    delta[i][x % 2] = Math.min(delta[i][x % 2], x);
                    delta[i][(x + 1) % 2] = Math.min(delta[i][(x + 1) % 2], -x);
                }
            }

            int[] bounds = new int[m + 1];
            for (int i = m - 1; i >= 0; i --)
                bounds[i] = Math.max(0, bounds[i + 1] - Math.max(delta[i][0], delta[i][1]));

            if (n <= bounds[0])
                System.out.println(-1);
            else {
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < m; i ++) {
                    if (n + delta[i][0] > bounds[i + 1]) {
                        sb.append("Even ");
                        n += delta[i][0];
                    }
                    else if (n + delta[i][1] > bounds[i + 1]) {
                        sb.append("Odd ");
                        n += delta[i][1];
                    }
                }
                System.out.println(sb.toString().trim());
            }
        }
    }
}

