public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        final int MAX = 1000000;
        int axisLength = scan.nextInt();
        int initialPosition = scan.nextInt();
        int position = initialPosition;
        int power = 1;
        boolean reverse = false;
        int breakCount = 0;
        int[] board = new int[axisLength];
        int[] target = new int[axisLength];
        int[] broken = new int[axisLength];
        Arrays.fill(board,-1);
        Arrays.fill(target,-1);
        Arrays.fill(broken,-1);
        for (int i = 0; i < axisLength; i++) {
            int judge = scan.nextInt();
            if (judge == 0) {
                board[i] = scan.nextInt();
            }else {
                target[i] = scan.nextInt();
                broken[i] = 0;
            }
        }
        if (board[initialPosition - 1] != -1) {
            power = power + board[initialPosition - 1];
            reverse = true;
        }else {
            if (power >= target[initialPosition - 1]) {
                broken[initialPosition - 1] = 1;
                breakCount++;
            }
        }
        for (int i = 0; i < MAX; i++) {
            if (! reverse) {
                position = position + power;
            }else {
                position = position - power;
            }
            if (position > axisLength || position <= 0) {
                break;
            }
            if (board[position - 1] != -1) {
                power = power + board[position - 1];
                reverse = ! reverse;
            }else {
                if (power >= target[position - 1] && broken[position - 1] != 1) {
                    broken[position - 1] = 1;
                    breakCount++;
                }
            }
        }
        System.out.println(breakCount);
    }
}

