            for (c = reader.read(); (!Character.isDigit(c)) && (c != '-'); c = reader.read()) {
            }
            if (c == '-') {
                f = -1;
                c = reader.read();
            }
            for (; c >= 0 && Character.isDigit(c); c = reader.read()) {
