            for (int j = 1; j <= 100; j++) {
                f[i][j] = 0;
                for (int d = 0; d <= Math.min(9, j); d++) {
                    f[i][j] += f[i - 1][j - d];
                }
            }
        }

        int T = getInt(reader);
