import java.util.*;

public class Main {
	 public static void main(String[] args) {
		  Scanner kb = new Scanner(System.in);
		  int t = kb.nextInt();
		  for (int i = 0; i < t; i ++) {
			   int n = kb.nextInt();
			   int[] opinions = new int[n];
			   Set<Integer> hs = new HashSet<>();
			   for (int j = 0; j < n; j ++)
					opinions[j] = kb.nextInt();

			   for (int j = 0; j < n - 1; j ++) {
					if (hs.contains(opinions[j]))
						 continue;
					if (opinions[j + 1] == opinions[j]) {
						 hs.add(opinions[j]);
					}
					else {
						 if (j < n - 2) {
							  if (opinions[j + 2] == opinions[j])
								   hs.add(opinions[j]);
						 }
					}
			   }
			   Integer[] a = hs.toArray(new Integer[0]);
			   if (hs.size() != 0) {
					Arrays.sort(a);
					for (int j = 0; j < a.length; j ++) {
						 if (j != a.length - 1)
							  System.out.print(a[j] + " ");
						 else
							  System.out.println(a[j]);
					}
			   }
			   else
					System.out.println(-1);
		  }
	 }
}

