import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.io.StreamTokenizer;
import java.util.Arrays;

public class Main {
    public static void main(String[] args) throws Exception{
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        st.nextToken(); int N = (int) st.nval;
        Stu[] stus = new Stu[N];
        int yw, sx, yy;
        for (int i = 0; i < N; i++) {
            st.nextToken(); yw = (int) st.nval;
            st.nextToken(); sx = (int) st.nval;
            st.nextToken(); yy = (int) st.nval;
            stus[i] = new Stu(i, yw, sx, yy);
        }
        Arrays.sort(stus, (o1, o2) -> compare(o1, o2));
        int[] rank = new int[N];
        rank[stus[0].no] = 1;
        int cnt = 1;
        for (int i = 1; i < N; i++) {
            if (compare(stus[i - 1], stus[i]) != 0) {
                cnt = i + 1;
            }
            rank[stus[i].no] = cnt;
        }
        for (int i = 0; i < N; i++) {
            pw.println(rank[i]);
        }
        pw.close();
    }

    static class Stu {
        public int no;
        public int tot;
        public int tot2;
        public int tot3;
        public Stu(int no, int yw, int sx, int yy) {
            this.no = no;
            this.tot = yw + sx + yy;
            this.tot2 = yw + sx;
            this.tot3 = Math.max(yw, sx);
        }
    }

    static int compare (Stu a, Stu b) {
        int k = b.tot - a.tot;
        if (k == 0) {
            k = b.tot2 - a.tot2;
            if (k == 0) {
                k = b.tot3 - a.tot3;
            }
        }
        return k;
    }
}

