        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int sum = 0;

        for (int i = 1; i <= n; i++) {
            if (isGoodNumber(i)) {
                sum++;
            }
        }

        System.out.println(sum);
    }

    private static boolean isGoodNumber(int number) {
        int temp = 0;
        int cnt = 1;
        int t = number;

        while (t > 0) {
            int digit = t % 10;


            if (cnt % 2 == 1 && digit % 2 != 1) { 
                temp = 1;
                break;
            }
            if (cnt % 2 == 0 && digit % 2 != 0) { 
                temp = 1;
                break;
            }

            t /= 10;
            cnt++;
        }

        return temp == 0;
    }
}

