    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Map<String, String[][]> map = new HashMap<>();
        for (int i = 0; i < n; i++) {
            String table = sc.next();
            int x = sc.nextInt(), y = sc.nextInt();
            String[][] ss = new String[x][y];
            for (int j = 0; j < x; j++) {
                for (int k = 0; k < y; k++) {
                    ss[j][k] = sc.next();
                }
            }
            map.put(table, ss);
        }
        int m = sc.nextInt();
        while (m-- > 0){
            String[] s =  new String[6];
            for (int i = 0; i < 6; i++) {
                s[i] = sc.next();
            }
            String col = s[1], table = s[3], condition = s[5];
            String[] cc = col.split(",");

            String[][] t = map.get(table);
            String[] ccc = condition.split("=");
            String a = ccc[0], b = ccc[1];
            int c = 0;
            int cnt = cc.length; 
            int[] index = new int[cnt];
            for(int i = 0; i < cnt; i++){
                for(int j = 0; j < t[0].length; j++){
                    if(t[0][j].equals(cc[i])){
                        index[i] = j;
                        break;
                    }
                }
            }
            for (int i = 0; i < t[0].length; i++) {
                if(a.equals(t[0][i])){
                    c = i;
                    break;
                }
            }
            for(int i = 1; i < t.length; i++){
                if(t[i][c].equals(b)){
                    for (int x : index) {
                        System.out.print(t[i][x] + " ");
                    }
                    System.out.println();
                }
            }
        }
    }

}

