for i in lst:
    measure = 0
    if i < 0:
        s = -i
        residue = m - s
        if residue <= 0:
            continue
        measure += left[s]
        residue -= s
        if residue > 0:
            measure += right[min(residue, N - 1)]
    else:
        s = i
        residue = m - s
        if residue <= 0:
            continue
        measure += right[s]
        residue -= s
        if residue > 0:
            measure += left[min(residue, N - 1)]
    if measure > max_measure:
        max_measure = measure
