import java.util.Scanner;


public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int[] l=new int[2*(int)Math.pow(10,6)+5];
        int[] r=new int[2*(int)Math.pow(10,6)+5];
        int count=0;
        int max=0;
        for (int i=1;i<=n;i++){
            int a= sc.nextInt();
            if (a<0) l[-a]++;
            else if (a>0) r[a]++;
            else count++;
        }
        for(int i=1;i<=m;i++){
            l[i]+=l[i-1];
            r[i]+=r[i-1];
        }
        for (int i=1;i<=m;i++){
            int b=l[i];
            if(m-i*2>0){
                b+=r[m-i*2];
            }
            max=Math.max(max,b);
            b=r[i];
            if(m-i*2>0){
                b+=l[m-i*2];
            }
            max=Math.max(max,b);
        }
        System.out.println(max+count);
        sc.close();
    }
}

