import java.util.*;
import java.io.*;
public class Main{
    static double eps=1e-5;
    public static void main(String args[]) throws IOException{
        BufferedReader bf=new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter bw=new BufferedWriter(new OutputStreamWriter(System.out));
        int t=Integer.parseInt(bf.readLine());
        for(int i=0;i<t;i++){
            String arr[]=bf.readLine().split(" ");
            int n=Integer.parseInt(arr[0]),m=Integer.parseInt(arr[1]),l=Integer.parseInt(arr[2]),V=Integer.parseInt(arr[3]),p[]=new int[m],ans1=0,ans2=0;
            double range[][]=new double[n][];
            for(int j=0;j<n;j++){
                arr=bf.readLine().split(" ");
                int d=Integer.parseInt(arr[0]),v=Integer.parseInt(arr[1]),a=Integer.parseInt(arr[2]);
                range[j]=find(d,v,a,V,l);
            }
            arr=bf.readLine().split(" ");
            for(int j=0;j<m;j++){
                p[j]=Integer.parseInt(arr[j]);
            }
            List<int[]> list=new ArrayList<>();
            for(double a[]:range){
                if(a!=null){
                    int low=find(p,a[0]),high=find(p,a[1]);
                    if(low<high){
                        ans1++;
                        list.add(new int[]{low+1,high});
                    }
                }
            }
            Collections.sort(list,(a,b)->a[1]-b[1]);
            for(int j=0;j<list.size();){
                int last=list.get(j)[1];
                while(j<list.size()&&list.get(j)[0]<=last){
                    j++;
                }
                ans2++;
            }
            bw.write(ans1+" "+(m-ans2)+"\n");
        }
        bw.flush();
    }
    static int find(int p[],double pos){
        if(p[0]>pos){
            return -1;
        }
        if(p[p.length-1]<=pos){
            return p.length-1;
        }
        int l=0,r=p.length-1;
        while(l<r){
            int mid=(l+r)>>1;
            if(p[mid]<=pos){
                l=mid;
            }
            else{
                r=mid-1;
            }
            if(l==r-1){
                if(p[r]<=pos){
                    l=r;
                }
                break;
            }
        }
        return l;
    }
    static double[] find(int d,int v,int a,int V,int l){
        if(v>V){
            if(a>=0){

                return new double[]{d-eps,l+1};
            }
            a=-a;

            double t=(v-V+0.0)/a;
            return new double[]{d-eps,d+v*t-a*t*t/2-eps};
        }
        else{
            if(a<=0){
                return null;
            }
            double t=(V-v+0.0)/a,dis=d+v*t+a*t*t/2;
            return dis<=l+1?new double[]{dis+eps,l+1}:null;
        }
    }
}

