import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scan=new Scanner(System.in);
        int n=scan.nextInt();
        long[] arr=new long[n+6];
        for (int i = 1; i <=n ; i++) {
            arr[i]=scan.nextLong();
        }
        long ans=Long.MAX_VALUE;
        for (int i = 1; i <=n; i++) {
            for (int j = i+1; j <=n; j++) {
                long suml=arr[i];
                long sumr=arr[j];
                int l=i-1;
                int r=j+1;
                long p=Math.abs(suml-sumr);
                ans=minnum(ans,p);
                while (l>=1&&r<=n){
                    if (suml>sumr){
                        sumr+=arr[r];
                        r++;
                    }else {
                        suml+=arr[l];
                        l--;
                    }
                    p=Math.abs(suml-sumr);
                    ans=minnum(ans,p);
                }
                while (l>=1){
                    suml+=arr[l];
                    l--;
                    p=Math.abs(suml-sumr);
                    ans=minnum(ans,p);
                }
                while (r<=n){
                    sumr+=arr[r];
                    r++;
                    p=Math.abs(suml-sumr);
                    ans=minnum(ans,p);
                }
            }
        }
        System.out.println(ans);
    }

    public static long minnum(long a,long b) {
        return Math.min(a, b);
    }
}

